window.DIGEST_ARCHIVE=window.DIGEST_ARCHIVE||{};window.DIGEST_ARCHIVE["2026-07-30"]={"date": "2026-07-30", "dateKR": "2026년 7월 30일", "dateEN": "30 July 2026", "total": 106, "sections": [{"code": "TOP", "type": "news", "kTitle": "Section 1. 주요 뉴스", "eTitle": "Section 1. Top News", "items": [{"code": "TOP", "title": "U.S. Launches Heavy Wave of Strikes on Iran", "src": "maritime-executive", "date": "2026-07-29", "kSum": "미 중부사령부(CENTCOM)가 7월 29일 요르단 주둔 미군 기지에 대한 이란의 미사일 공격에 대응해 이란 내 지휘부, 드론·미사일 발사장, 연안 감시시설, 해상 전력 등 수십 개 표적을 재차 공습했다. 호르무즈 해협 상선 공격을 겨냥한 군사작전의 연장선이다.", "eSum": "On July 29, U.S. Central Command launched a fresh wave of airstrikes on Iranian command centers, drone and missile launch sites, coastal surveillance and maritime targets in response to Iranian missile attacks on U.S. bases in Jordan, part of the campaign tied to attacks on Strait of Hormuz shipping.", "kImp": "미-이란 무력충돌 심화로 호르무즈·홍해 해상 안보 리스크가 커지고 유가와 운임 변동성이 확대된다.", "eImp": "Deepening U.S.-Iran hostilities raise maritime security risk and freight and oil price volatility across Hormuz and the Red Sea.", "url": "https://maritime-executive.com/article/u-s-launches-heavy-wave-of-strikes-on-iran"}, {"code": "TOP", "title": "U.S. Sanctions Two Iran-Linked Firms Over Hormuz Transit Fees", "src": "maritime-executive", "date": "2026-07-29", "kSum": "미 재무부가 7월 29일 이란 혁명수비대(IRGC)의 호르무즈 해협 통항료·보험 구조 중심으로 지목한 두 업체(Persian Gulf Marine Insurance, HormuzSafe Marine Services Authority)를 제재했다. IRGC가 자신들의 공격으로부터 선박을 보호한다는 명목의 보험 사업이다.", "eSum": "On July 29 the U.S. Treasury sanctioned two firms, Persian Gulf Marine Insurance Company and HormuzSafe Marine Services Authority, described as central to the IRGC's Strait of Hormuz transit-fee and insurance scheme that purports to protect ships from the IRGC's own attacks.", "kImp": "이란의 호르무즈 통항료 부과 시도를 겨냥한 제재로 선주와 보험사의 컴플라이언스 부담과 통항 비용 불확실성이 커진다.", "eImp": "Aimed at Iran's attempt to monetize Hormuz transits, the sanctions raise compliance burdens and cost uncertainty for owners and insurers.", "url": "https://maritime-executive.com/article/u-s-sanctions-two-insurers-for-handling-iran-s-hormuz-transit-fees"}, {"code": "TOP", "title": "EU Implements New Critical Infrastructure Risk System", "src": "maritime-executive", "date": "2026-07-29", "kSum": "EU가 필수 서비스에 중요한 기반시설의 리스크 완화 체계를 이달 시행에 들어갔다. 회원국은 7월 17일까지 중요 기반시설 운영 주체를 식별하고, 이후 운영자는 취약성 평가와 모니터링·완화 방안을 수립해야 한다.", "eSum": "The EU has begun implementing a new critical-infrastructure risk-mitigation regime; by July 17 member states were to identify operators of essential-service infrastructure, which must then assess vulnerabilities and set out monitoring and mitigation.", "kImp": "해저케이블·파이프라인·항만 등 해상 기반시설 보호 의무가 강화되며 사업자의 규제 부담이 증가한다.", "eImp": "Protection obligations tighten for maritime infrastructure such as subsea cables, pipelines and ports, increasing operator compliance duties.", "url": "https://maritime-executive.com/article/eu-implements-new-critical-infrastructure-risk-system"}, {"code": "TOP", "title": "CMA CGM and Stonepeak Complete $2.4B United Ports Terminal JV", "src": "maritime-executive", "date": "2026-07-28", "kSum": "CMA CGM와 인프라 투자사 Stonepeak가 그룹 항만터미널 성장에 투자하는 합작사 United Ports 설립을 완료했다고 7월 28일 발표했다. Stonepeak가 24억 달러를 투자한다.", "eSum": "CMA CGM and infrastructure investor Stonepeak announced on July 28 the completion of their United Ports joint venture, with Stonepeak investing $2.4 billion to grow the group's port terminals.", "kImp": "컨테이너 선사의 항만 인프라 수직계열화가 심화되는 대형 자본거래로 터미널 경쟁 구도에 영향을 준다.", "eImp": "A major capital deal deepening carriers' vertical integration into port infrastructure, reshaping terminal competition.", "url": "https://maritime-executive.com/article/cma-cgm-plans-growth-in-port-terminals-with-2-4b-investment-from-stonepeak"}, {"code": "TOP", "title": "Iran Rejects Omani Proposal for Joint Governance of Strait of Hormuz", "src": "maritime-executive", "date": "2026-07-28", "kSum": "이란이 오만이 제시한 호르무즈 해협 공동관리 제안을 거부했다고 7월 28일 보도됐다. 해협의 통항분리대(TSS)는 오만 수역에 있으나, 이란은 드론·미사일로 남측 해역 통항을 사실상 차단해왔다.", "eSum": "Iran has rejected Oman's latest proposal to share control of the Strait of Hormuz, reported July 28; the strait's traffic separation scheme lies in Omani waters, but Iran has used drones and missiles to halt most traffic in the southern half of the waterway.", "kImp": "해협 정상화 협상이 교착되며 통항 중단 장기화와 우회·대체 물류 부담이 지속된다.", "eImp": "Stalled negotiations prolong the transit shutdown and sustain rerouting and logistics costs.", "url": "https://maritime-executive.com/article/iran-rejects-proposal-for-joint-governance-of-hormuz"}, {"code": "TOP", "title": "HD Hyundai Launches First Newbuild at Revitalized Subic Shipyard", "src": "maritime-executive", "date": "2026-07-29", "kSum": "HD현대(HD Hyundai)가 필리핀 수빅베이의 옛 한진중공업 조선소를 인수·재가동해 첫 신조선인 11만5천 dwt 석유화학제품운반선 Orion Jade를 7월 29일 진수했다. 이 조선소는 2019년 가동을 중단했었다.", "eSum": "HD Hyundai launched its first newbuild, the 115,000 dwt petrochemical tanker Orion Jade, on July 29 at the former Hanjin yard in Subic Bay, Philippines, which the Korean builder took over and restarted after operations there ceased in 2019.", "kImp": "한국 조선사의 동남아 생산기지 확장으로 글로벌 건조능력 재편과 지역 조선업 부활의 신호가 된다.", "eImp": "A Korean builder's Southeast Asian expansion signals shifting global shipbuilding capacity and a regional shipbuilding revival.", "url": "https://maritime-executive.com/article/hd-hyundai-launches-first-ship-from-revitalized-philippine-shipyard"}, {"code": "TOP", "title": "Eni and TotalEnergies Take FID on Cyprus Cronos Gas Project", "src": "maritime-executive", "date": "2026-07-28", "kSum": "Eni와 TotalEnergies가 7월 28일 키프로스 EEZ 내 Cronos 가스전 최종투자결정(FID)을 내렸다. 이집트 Damietta LNG 터미널로 파이프라인 연결해 2028년 개발 목표이며 매장량은 약 3조 입방피트로 추정된다.", "eSum": "Eni and TotalEnergies took a final investment decision on July 28 for the Cronos gas field in Cyprus's EEZ, to be tied by pipeline to Egypt's Damietta LNG terminal and developed by 2028, with an estimated three trillion cubic feet of gas.", "kImp": "동지중해 가스 개발과 LNG 수출 인프라 재가동으로 역내 에너지 해상물류에 새 수요가 형성된다.", "eImp": "East Med gas development and revived LNG export infrastructure create new regional energy shipping demand.", "url": "https://maritime-executive.com/article/eni-and-totalenergies-give-green-light-for-cyprus-cronos-gas-project"}, {"code": "TOP", "title": "Royal Caribbean Posts Strong Q2 Despite Fuel and Geopolitical Pressure", "src": "maritime-executive", "date": "2026-07-28", "kSum": "로열캐리비안그룹(Royal Caribbean Group)이 7월 28일 시장 예상을 웃도는 2분기 실적을 발표했다. 총매출 6% 증가, 승객 240만명(6%↑), 적재율 110%였으나 연료비가 전년 대비 27% 상승해 마진은 하락했다. 연간 전망은 상향했다.", "eSum": "Royal Caribbean Group reported better-than-expected second-quarter results on July 28 with revenue up 6%, 2.4 million passengers and a 110% load factor, though fuel costs rose 27% year-on-year and pressured margins; it raised its full-year guidance.", "kImp": "지정학 리스크와 연료비 부담 속에서도 크루즈 수요의 견조함을 확인시켜 준 실적이다.", "eImp": "The results confirm resilient cruise demand despite geopolitical risk and higher fuel costs.", "url": "https://maritime-executive.com/article/royal-caribbean-posts-strong-q2-despite-fuel-costs-geopolitical-impact"}, {"code": "TOP", "title": "Lloyd's Clause Lets Insurers Void Cover If Owners Pay Iran for Hormuz Transit", "src": "maritime-executive", "date": "2026-07-23", "kSum": "로이즈시장협회(LMA)가 호르무즈 해협 통항 보험에 대해, 선주가 이란에 통항료를 지불한 사실이 확인되면 보험을 취소할 수 있는 선택 조항을 마련했다고 7월 23일 보도됐다. 보험사를 컴플라이언스 리스크로부터 보호하기 위한 것이다.", "eSum": "The Lloyd's Market Association has drafted an optional clause allowing insurers to cancel Strait of Hormuz transit cover if an owner is found to have paid a toll to Iran, reported July 23, to shield insurers from compliance risk.", "kImp": "이란 통항료를 둘러싼 보험·제재 리스크가 선주의 통항 의사결정을 더욱 압박한다.", "eImp": "Insurance and sanctions risk over Iranian tolls further pressures owners' transit decisions.", "url": "https://maritime-executive.com/article/marine-insurers-may-ban-payments-to-iran-for-hormuz-transits"}, {"code": "TOP", "title": "Nigerian Navy Detains Chinese-Owned Tanker Over Alleged Oil Theft", "src": "maritime-executive", "date": "2026-07-29", "kSum": "나이지리아 해군이 7월 29일 원유를 불법 적재한 혐의로 중국 소유 소형 탱커 Filia(3,158 dwt)와 승선원을 억류했다고 공개했다. 해상 원유 절도 단속의 일환으로, 해당 선박은 해상터미널 인근에 7일 이상 머문 것으로 감시됐다.", "eSum": "The Nigerian Navy announced on July 29 the detention of the Chinese-owned tanker Filia (3,158 dwt) and its crew for allegedly loading crude oil without authorization, part of a crackdown on offshore oil theft after the ship lingered near an offshore terminal for more than seven days.", "kImp": "서아프리카 해상 원유 절도·불법 환적 단속 강화로 관련 선박·운영자의 규제 리스크가 부각된다.", "eImp": "Intensified West African enforcement against oil theft and illicit transfers highlights regulatory risk for vessels and operators.", "url": "https://maritime-executive.com/article/nigerian-navy-detains-chinese-owned-tanker-accused-of-stealing-oil"}]}, {"code": "ACC", "type": "accident", "kTitle": "Section 2. 해양사고", "eTitle": "Section 2. Accidents", "items": [{"code": "ACC", "title": "Two LNG Carriers Struck in Drone Attack at Egypt's Damietta Port", "src": "maritime-executive", "date": "2026-07-29", "kSum": "LNG선 Gaslog Salem과 Energos Winter 2척이 7월 29일 14:20(GMT) 이집트 지중해 연안 Damietta 항 부두에서 드론 공격으로 동시 피격돼 화재가 발생했다. 이집트 소방·예인선 대응으로 진화됐고 양 선박 모두 인명피해는 없었다.", "eSum": "Two LNG carriers, Gaslog Salem and Energos Winter, were struck simultaneously by drones at the dockside of Egypt's Damietta port at 14:20 GMT on July 29, causing fires that Egyptian firefighters and rescue tugs extinguished with no casualties on either ship.", "kCause": "장거리 드론 공격으로, 후티 등 이란 연계 세력의 소행일 가능성이 제기된다(추정). 정식 조사와 배후 확인은 진행 중이다.", "eCause": "An apparent long-range drone attack, possibly by Houthi or Iran-aligned forces (presumed); attribution was not confirmed.", "kLes": "LNG 터미널·정박 선박의 드론 위협 노출과 신속한 항만 비상대응의 중요성이 부각된다(추정).", "eLes": "Highlights the drone-threat exposure of LNG terminals and berthed ships and the value of rapid port emergency response (presumed).", "url": "https://maritime-executive.com/article/lng-tankers-struck-in-apparent-drone-attack-on-egypt-s-port-of-damietta"}, {"code": "ACC", "title": "Saudi Product Tanker NCC Ghazal Hit by Houthi Missiles in Red Sea", "src": "maritime-executive", "date": "2026-07-28", "kSum": "사우디 국적 5만 dwt 제품운반선 NCC Ghazal이 7월 28일경 홍해에서 후티의 대함미사일에 피격됐다. 선박은 회항해 항구로 복귀했으며 인명피해 보고는 없다. 이 선박은 7월 23일 AIS에서 사라졌고 마지막 위치는 사우디 얀부항이었다.", "eSum": "The Saudi-flagged 50,000 dwt product tanker NCC Ghazal was struck by Houthi antiship missiles in the Red Sea around July 28; it turned back to port with no reported casualties, having disappeared from AIS on July 23 near the Saudi oil port of Yanbu.", "kCause": "후티가 사우디에 부과한 해상 봉쇄를 위반했다는 이유로 탄도미사일 공격을 감행했다고 주장했다.", "eCause": "The Houthis claimed a ballistic-missile strike over the tanker's alleged violation of their maritime blockade of Saudi Arabia.", "kLes": "사우디 연계 선박에 대한 후티 공격 확대로 홍해 에너지 물류의 위험이 급증하고 있다(추정).", "eLes": "Expanding Houthi strikes on Saudi-linked ships sharply raise Red Sea energy-shipping risk (presumed).", "url": "https://maritime-executive.com/article/saudi-tanker-hit-by-houthi-missiles-in-the-red-sea"}, {"code": "ACC", "title": "Explosion and Fire on Norwegian Sulfuric Acid Tanker Bergstraum", "src": "maritime-executive", "date": "2026-07-28", "kSum": "황산을 실은 노르웨이 국적 탱커 Bergstraum(9,494 dwt)에서 7월 28일 15:33(현지) 프레드릭스타드 인근 오슬로피오르 입구 해상에서 폭발과 화재가 발생했다. 발트·필리핀 선원 15명 전원이 무사했고 부상자는 없었으며 화재는 진화됐다.", "eSum": "An explosion and fire broke out at 15:33 local on July 28 aboard the Norwegian sulfuric-acid tanker Bergstraum (9,494 dwt) off Fredrikstad near the entrance to the Oslo Fjord; all 15 Baltic and Filipino crew were unhurt and the fire was extinguished.", "kCause": "빈 탱크 내부에서 폭발이 발생해 주화물에는 영향이 없었다고 선사가 밝혔으며, 정확한 원인은 조사 중이다(추정).", "eCause": "The operator said the explosion occurred in an empty tank and did not affect the main cargo; the exact cause is under investigation (presumed).", "kLes": "위험화물(황산) 운반선의 탱크 관리와 가스 위험 통제, 인화 방지의 필요성이 확인된다(추정).", "eLes": "Points to tank management, gas-hazard control and ignition prevention on dangerous-cargo (sulfuric acid) tankers (presumed).", "url": "https://maritime-executive.com/article/explosion-and-fire-on-norwegian-tanker-carrying-sulfuric-acid"}, {"code": "ACC", "title": "Viking River Cruise Ship Viking Ullur Grounds on the Danube", "src": "maritime-executive", "date": "2026-07-29", "kSum": "스위스 선적 강 크루즈선 Viking Ullur이 7월 28일 02:20경 불가리아 비딘 상류 약 15마일 지점 다뉴브강에서 좌초했다. 승객 186명과 승무원 52명이 탑승했고 부상자는 없었으며, 7월 29일 주간에 승객 대피가 이뤄졌다.", "eSum": "The Swiss-flagged river cruise ship Viking Ullur grounded on the Danube about 15 miles above Vidin, Bulgaria at around 02:20 on July 28; its 186 passengers and 52 crew were unhurt and evacuated during daylight on July 29.", "kCause": "가뭄·폭염에 따른 극단적 저수위와 야간 항해 중 항로 이탈이 원인으로 지목됐고, 한 승객은 도선사 과실이라고 전했다(추정).", "eCause": "Extreme low water from drought and heat, plus leaving the navigable channel during night navigation, were cited; a passenger said they were told it was pilot error (presumed).", "kLes": "저수위 시기 흘수제한 준수와 항로 유지, 야간항행 주의의 중요성이 강조된다.", "eLes": "Underlines compliance with draft restrictions and channel-keeping and night-navigation caution during low water.", "url": "https://maritime-executive.com/article/viking-river-cruise-ship-evacuated-after-grounding-on-the-danube"}, {"code": "ACC", "title": "Grounded Cargo Ship Onego Otra Refloated in St. Lawrence River", "src": "maritime-executive", "date": "2026-07-28", "kSum": "곡물을 실은 소형 화물선 Onego Otra(10,872 dwt)가 캐나다 세인트로렌스강 Ile Saint-Ours 인근에서 수 주간 좌초해 있다가 7월 28일 이초(refloat)됐다. 손상 여부 확인을 위한 검사가 진행 중이며 인명피해는 보고되지 않았다.", "eSum": "The small grain-laden cargo ship Onego Otra (10,872 dwt), aground for weeks near Ile Saint-Ours in Canada's St. Lawrence River, was refloated on July 28 and is being inspected for damage; no casualties were reported.", "kCause": "6월 30일 몬트리올 출항 후 강에서 방향타 이상으로 항로를 벗어나 좌초한 것으로 보고됐다.", "eCause": "The vessel reportedly suffered a rudder problem and veered off course in the river after departing Montreal on June 30.", "kLes": "조타장치 고장 대응과 하천 항행 안전관리, 조기 이초 계획의 중요성이 확인된다(추정).", "eLes": "Highlights steering-failure response, river-navigation safety management and prompt refloating planning (presumed).", "url": "https://maritime-executive.com/article/cargo-ship-stuck-for-weeks-is-refloated-in-the-st-lawrence-river"}, {"code": "ACC", "title": "River Cruise Ship Anna Katharina Hits Lock Wall in Vienna", "src": "maritime-executive", "date": "2026-07-24", "kSum": "강 크루즈선 Anna Katharina(2019년 건조, 135m)가 7월 24일 04:30경 오스트리아 빈의 다뉴브강 Freudenau 발전소 갑문 벽에 충돌했다. 약 200명이 탑승했고 14명이 경상, 그중 6명이 병원으로 이송됐다.", "eSum": "The river cruise ship Anna Katharina (135m, built 2019) struck the lock wall at Vienna's Freudenau power plant on the Danube at about 04:30 on July 24; of roughly 200 people aboard, 14 suffered light injuries and 6 were taken to hospital.", "kCause": "사고 원인은 조사 및 사법 조사가 진행 중이며, 경찰은 기술적 결함 가능성을 검토하고 있다(추정).", "eCause": "The cause is under investigation with a judicial inquiry; police are considering a possible technical defect (presumed).", "kLes": "갑문 접근·조선(操船) 절차와 기관·조타 신뢰성 점검, 승객 안전관리의 필요성이 확인된다(추정).", "eLes": "Points to lock-approach and ship-handling procedures, machinery and steering reliability checks and passenger safety (presumed).", "url": "https://maritime-executive.com/article/cruise-ship-hits-lock-wall-in-vienna-injuring-14-people"}, {"code": "ACC", "title": "Seafarer Dies From Wounds After Drone Strike on LPG Carrier Gas Lisbon", "src": "maritime-executive", "date": "2026-07-23", "kSum": "터키 소유 LPG선 Gas Lisbon(프로판 약 3,800톤)이 일요일 루마니아 연안 약 20해리 지점에서 러시아 드론 다발에 피격돼 폭발과 화재가 났다. 선원 17명 중 3명이 부상했고, 7월 23일 45세 필리핀 선원 1명이 화상 합병증으로 사망, 2명은 중환자실 치료 중이다.", "eSum": "The Turkish-owned LPG carrier Gas Lisbon (about 3,800 t of propane) was hit by multiple Russian drones some 20 nm off Romania on Sunday, causing an explosion and fire; of 17 crew, three were injured and a 45-year-old Filipino sailor died on July 23 from burn complications, with two others in intensive care.", "kCause": "우크라이나(레니)행 항해 중 러시아 드론 공격을 받은 것으로, 흑해 상선을 겨냥한 광범위한 공격 캠페인의 일부다.", "eCause": "The vessel, inbound for Reni, Ukraine, was struck by Russian drones as part of the broader campaign of strikes against Black Sea merchant shipping.", "kLes": "흑해 항로에서 상선과 선원을 겨냥한 공격 위험이 치명적 수준으로 고조되고 있다(추정).", "eLes": "Attacks on merchant ships and crews in the Black Sea have escalated to a lethal level (presumed).", "url": "https://maritime-executive.com/article/sailor-aboard-lpg-carrier-gas-lisbon-dies-of-his-wounds"}, {"code": "ACC", "title": "Broken Wind Turbine Blade Adrift in North Sea Posed Navigation Hazard", "src": "maritime-executive", "date": "2026-07-28", "kSum": "독일 보르쿰섬 북측 북해에서 부러진 풍력터빈 날개가 표류하며 항행에 중대한 위험을 초래했고, 7월 28일 독일 연방경찰이 이를 회수했다. 인명피해는 없었다.", "eSum": "A broken wind turbine blade drifting in the North Sea north of Germany's Borkum island posed a significant navigation hazard and was recovered by the German Federal Police on July 28; there were no casualties.", "kCause": "인근에서 건설 중인 해상풍력단지에서 떨어져 나온 날개로 추정된다(추정).", "eCause": "The blade is believed to have come from a nearby under-construction offshore wind farm (presumed).", "kLes": "해상풍력 구조물 파손 잔해가 항행 위험이 될 수 있어 감시·경보·회수 체계가 필요하다.", "eLes": "Debris from offshore wind structures can endanger navigation, requiring monitoring, warning and recovery systems.", "url": "https://maritime-executive.com/article/broken-wind-turbine-blade-in-north-sea-was-a-menace-to-shipping"}, {"code": "ACC", "title": "Wind Orca Allision at Port of Tyne Releases Billion Plastic Nurdles", "src": "maritime-executive", "date": "2026-07-28", "kSum": "설치선(WTIV) Wind Orca가 영국 타인항에서 계류 중이던 컨테이너선 BG Orange와 충돌해 컨테이너가 파손되면서 약 10억 개의 플라스틱 펠릿(너들)이 유출됐다. 갠트리 크레인이 붕괴했고 1명이 병원으로 이송됐다.", "eSum": "The WTIV Wind Orca allided with the moored container ship BG Orange at the UK's Port of Tyne, damaging containers and releasing about one billion plastic nurdles; a gantry crane collapsed and one person was evacuated to hospital.", "kCause": "충돌(allision) 사고의 원인은 조사가 진행 중이다(추정).", "eCause": "An investigation into the cause of the allision is under way (presumed).", "kLes": "항내 조선·충돌 방지와 함께 펠릿 등 난제거성 해양오염에 대한 대응·정화 체계의 필요성이 부각된다.", "eLes": "Highlights in-port ship-handling and collision avoidance plus response and cleanup for persistent pollution such as nurdle spills.", "url": "https://maritime-executive.com/article/casualty-at-port-of-tyne-caused-large-release-of-plastic-nurdles"}, {"code": "ACC", "title": "USCGC Healy Icebreaker Suffers Significant Engineering Casualty", "src": "maritime-executive", "date": "2026-07-24", "kSum": "미 해안경비대 중형 쇄빙선 USCGC Healy가 워싱턴주 포트앤젤레스 인근 해상에서 7월 13일 중대한 기관 손상을 입었고 7월 24일 보도됐다. 부상자는 없었으며 예인돼 시애틀 모항으로 복귀했고 대규모 수리가 예정돼 있다.", "eSum": "The U.S. Coast Guard medium icebreaker USCGC Healy suffered a significant engineering casualty off Port Angeles, Washington on July 13, reported July 24; there were no injuries and she was towed to her Seattle homeport for major repairs.", "kCause": "4개 주기관 중 하나에서 크랭크케이스 폭발이 있었던 것으로 업계에서 지목되나, USCG는 손상의 성격을 특정하지 않았다(추정).", "eCause": "Industry sources indicate a crankcase explosion in one of her four main engines, though the USCG did not specify the nature of the casualty (presumed).", "kLes": "노후 쇄빙선의 기관 신뢰성 문제와 미국 쇄빙 함대 가용성의 취약성이 다시 드러났다(추정).", "eLes": "Underscores aging-icebreaker machinery reliability and the thin availability of the U.S. icebreaker fleet (presumed).", "url": "https://maritime-executive.com/article/one-of-america-s-three-icebreakers-suffers-significant-breakdown"}]}, {"code": "PSC", "type": "news", "kTitle": "Section 3. 항만국통제", "eTitle": "Section 3. Port State Control", "items": [{"code": "PSC", "title": "IMO, 항만국통제(PSC) 점검·검사관 교육 국제 조화 방안 진전", "src": "SAFETY4SEA", "date": "2026-07-28", "kSum": "국제해사기구(IMO)가 전 세계 항만국통제(PSC) 점검의 일관성과 실효성을 높이기 위한 조치를 진전시켰다. 2026년 7월 20~24일 런던에서 열린 IMO 협약이행 소위원회 제12차 회기(III 12)에서 기관·정비 관련 점검, 항만국통제관(PSCO)의 자격 요건, 신규 PSC 인력 교육 방안이 집중 논의됐다. 이는 결의 A.1206(34)로 채택된 '2025 항만국통제 절차서'의 2027년 개정 작업의 일환이다. IMO 절차서는 강제 규정은 아니지만 파리 MoU·도쿄 MoU 등 지역 PSC 체제에서 광범위하게 적용되어 점검·결함 판정·통제 조치의 글로벌 기준으로 통용된다.", "eSum": "The IMO has advanced measures to improve the consistency and effectiveness of Port State Control (PSC) inspections worldwide. At the 12th session of IMO's Sub-Committee on Implementation of IMO Instruments (III 12), held in London on 20-24 July 2026, delegates focused on machinery and maintenance inspections, the qualifications of Port State Control Officers (PSCOs) and the training of personnel entering the PSC system. The work forms part of the 2027 revision of the Procedures for Port State Control, 2025, adopted through resolution A.1206(34). Though not mandatory, the IMO Procedures are widely applied by regional regimes including the Paris and Tokyo MoUs and are regarded as the global benchmark.", "kImp": "PSCO 자격·교육과 기관·정비 점검 기준이 조화·강화되면 선령이 높거나 정비 이력이 약한 선박의 결함·억류 노출이 커진다. 2027년 절차서 개정과 개정 EU PSC 지침(2027.7.6 발효)을 앞두고 선사·선박관리사는 SMS 실효성, 기관 정비 기록, 승무원 숙련도를 선제 점검해 대비할 필요가 있다.", "eImp": "As PSCO qualification/training and machinery-maintenance inspection standards are harmonised and tightened, ships that are older or have weaker maintenance records face greater exposure to deficiencies and detention. Ahead of the 2027 Procedures revision and the amended EU PSC Directive (effective 6 July 2027), owners and managers should proactively verify SMS effectiveness, machinery maintenance records and crew competence.", "url": "https://safety4sea.com/cm-imo-advances-harmonized-psc-inspections-and-officer-training/"}]}, {"code": "PCTC", "type": "news", "kTitle": "Section 4. 자동차운반선", "eTitle": "Section 4. PCTC / Car Carriers", "items": [{"code": "PCTC", "title": "살라움 라인, 중국 자오상 진링조선소에 8,600CEU 이중연료 PCTC 추가 발주", "src": "Baird Maritime", "date": "2026-07-29", "kSum": "스위스 선사 살라움 라인(Sallaum Lines)이 7월 28일 중국 자오상 진링조선소(China Merchants Jinling Shipyard)와 8,600CEU급 순수차량운반선(PCTC) 1척(옵션 1척 포함) 건조 계약을 체결했다. 선박은 전장 199.99m, 폭 38m, 공기흘수 46m로, 기존 선박 대비 최대 1,100대 더 실을 수 있다. 추진 시스템은 LNG·MGO·초저유황유(VLSFO)를 쓸 수 있고 향후 암모니아 연료로 개조 가능하다. 인도는 2029년 예정이며, 이 발주로 살라움의 신조 프로그램은 9척(총 8억5,000만 달러 이상)으로 늘었다.", "eSum": "Swiss operator Sallaum Lines signed a contract on 28 July with China Merchants Jinling Shipyard for one (plus one optional) 8,600 CEU pure car and truck carrier (PCTC). The vessel measures 199.99 m LOA, 38 m beam and 46 m air draught, and can carry up to 1,100 more vehicles than its predecessors. Its propulsion can run on LNG, MGO and VLSFO and may later be converted to ammonia. Delivery is scheduled for 2029, bringing Sallaum's newbuilding programme to nine vessels worth over USD 850 million.", "kImp": "중국 조선소를 통한 대체연료 PCTC 발주 확대는 차량 수출 급증에 대응한 선복 증강 흐름을 보여준다. 다만 2026년 세계 PCTC 선대가 약 7.6% 늘어 공급이 수요를 앞지르는 국면이어서 용선료·자산가치 조정 압력이 커질 수 있고, 한국 완성차·자동차물류 업계의 선복 확보 전략에도 영향을 준다.", "eImp": "The wave of alternative-fuel PCTC ordering at Chinese yards reflects capacity building to meet surging vehicle exports. However, with the global PCTC fleet set to grow ~7.6% in 2026 and supply outpacing demand, charter rates and asset values face downward pressure, with implications for Korean automakers' and vehicle-logistics players' capacity strategies.", "url": "https://www.bairdmaritime.com/shipping/dry-cargo/pcc-pctc/sallaum-lines-selects-chinese-builder-for-new-dual-fuel-car-carrier"}, {"code": "PCTC", "title": "DP월드, 다르에스살람항 로로 개편으로 차량 양하 시간 90% 단축", "src": "Heavy Lift & Project Forwarding International (HLPFI)", "date": "2026-07-27", "kSum": "DP월드(DP World)가 탄자니아 다르에스살람항(Dar es Salaam)의 로로(ro-ro) 하역을 대폭 개편해, PCTC 전용 하역 방식을 도입한 뒤 차량 양하 시간을 90% 단축했다. 중장비 차량 하역의 속도와 안전성도 함께 개선됐다. 이는 아프리카 관문항에서 차량 화물 처리 역량을 끌어올린 사례로, 급증하는 차량 수입·환적 물량에 대응하는 터미널 인프라 고도화를 보여준다.", "eSum": "DP World has overhauled ro-ro operations at Tanzania's port of Dar es Salaam, cutting vehicle discharge times by 90 percent after introducing dedicated PCTC handling, while also improving the speed and safety of heavy-duty vehicle discharge. The upgrade lifts vehicle-cargo handling capacity at a key African gateway and illustrates terminal-infrastructure modernisation to cope with rising vehicle import and transhipment volumes.", "kImp": "PCTC 대형화로 대응 가능한 부두가 제한된 상황에서 항만 하역 효율 개선은 선박 회전율과 정박 시간을 좌우하는 핵심 변수다. 신흥국 관문항의 처리 능력 향상은 아프리카·중동 항로를 운영하는 차량운반선사의 스케줄 안정성과 총 운송비 절감에 직접 기여한다.", "eImp": "With relatively few berths able to handle ever-larger PCTCs, port handling efficiency is a decisive factor for vessel turnaround and berth time. Raising throughput at emerging-market gateways directly improves schedule reliability and lowers total transport costs for car-carrier operators serving Africa and Middle East trades.", "url": "https://www.heavyliftpfi.com/ports-and-terminals/2026/07/27/dar-es-salaams-ro-ro-revamp-transforms-handling-times/"}, {"code": "PCTC", "title": "한국해양진흥공사(KOBC), LNG 이중연료 신조 차량운반선 '글로비스 노바' 인도", "src": "Baird Maritime", "date": "2026-07-23", "kSum": "한국해양진흥공사(Korea Ocean Business Corporation, KOBC)가 광저우조선국제(Guangzhou Shipyard International)에서 건조한 신형 LNG 이중연료 순수차량운반선(PCTC) '글로비스 노바(Glovis Nova)'를 인도받았다. 이 선박은 LNG를 주연료로 운항할 수 있는 친환경 차량운반선으로, 한국 선사·차량물류 진영의 대체연료 선대 확충 흐름을 잇는 사례다.", "eSum": "Korea Ocean Business Corporation (KOBC) has taken delivery of Glovis Nova, a new LNG dual-fuel pure car and truck carrier (PCTC) built by Guangzhou Shipyard International. Capable of running primarily on LNG, the vessel adds to the growing alternative-fuel car-carrier tonnage associated with Korean owners and vehicle-logistics interests.", "kImp": "완성차 수출 확대와 환경 규제 강화 속에서 LNG 이중연료 PCTC 인도는 한국 자동차 해상운송의 경쟁력과 탈탄소 대응력을 높인다. 중국 조선소를 통한 신조 인도가 이어지면서, 국적 선사·화주의 안정적 선복 확보와 배출 규제 대응이 한층 유리해진다.", "eImp": "Amid expanding finished-vehicle exports and tightening environmental rules, delivery of LNG dual-fuel PCTCs strengthens the competitiveness and decarbonisation readiness of Korea's automotive maritime transport. Continued newbuild deliveries from Chinese yards improve secure capacity access and emissions-regulation compliance for Korean owners and shippers.", "url": "https://www.bairdmaritime.com/shipping/dry-cargo/pcc-pctc/korea-ocean-business-corporation-takes-delivery-of-new-lng-dual-fuel-car-carrier"}]}, {"code": "EE", "type": "news", "kTitle": "Section 6. 에너지 효율·탈탄소", "eTitle": "Section 6. Energy Efficiency", "items": [{"code": "EE", "title": "Maersk Tankers and HD Hyundai Samho Celebrate First Large Ammonia Carrier", "src": "maritime-executive", "date": "2026-07-28", "kSum": "머스크 탱커스(Maersk Tankers)가 HD현대삼호가 건조한 첫 초대형 암모니아 운반선(VLAC) '제인 머스크(Jane Maersk)'를 인도받았다. 9만3,000㎥급으로 암모니아와 LPG를 함께 운송할 수 있으며, 총 10척 시리즈의 첫 선박이다. HD현대삼호의 VLAC 수주잔량은 22척·25억5,000만 달러로 늘었다.", "eSum": "Maersk Tankers took delivery of Jane Maersk, its first very large ammonia carrier (VLAC), a 93,000 cbm dual-capable vessel for ammonia and LPG built by HD Hyundai Samho. It is the first of 10 such ships, and the yard's VLAC orderbook has grown to 22 vessels worth $2.55bn.", "kImp": "암모니아가 실증 단계를 넘어 상업적 해상 운송으로 전환되고 있음을 보여주며, 차세대 가스·대체연료 운반선 분야에서 한국 조선소의 우위를 강화한다.", "eImp": "The delivery signals ammonia's shift from concept to commercial-scale seaborne trade and strengthens Korean yards' lead in next-generation gas and alternative-fuel carriers.", "url": "https://maritime-executive.com/article/maersk-tankers-and-hd-hyundai-samho-celebrate-first-large-ammonia-carrier"}, {"code": "EE", "title": "Portsmouth starts operating shore power system to lower emissions", "src": "safety4sea", "date": "2026-07-28", "kSum": "영국 포츠머스 국제항(Portsmouth International Port)이 육상전력(shore power) 시스템 가동을 시작했다. 페리와 크루즈선이 접안 중 엔진을 끄고 육상 전기에 연결할 수 있어, 항만의 2050년 무배출 목표 달성을 지원한다.", "eSum": "Portsmouth International Port has begun operating a shore power (cold ironing) system that lets ferries and cruise ships plug into shore electricity and shut down engines at berth, part of its plan to reach zero emissions by 2050.", "kImp": "접안 중 대기오염과 CO2를 줄이는 항만 전기화 사례로, 항만에 육상전력 공급을 요구하는 규제·지역사회 압력이 커지고 있음을 보여준다.", "eImp": "Port-side electrification cuts at-berth air pollution and CO2 and reflects growing regulatory and community pressure on ports to provide shore power.", "url": "https://safety4sea.com/portsmouth-starts-operating-shore-power-system-to-lower-emissions/"}, {"code": "EE", "title": "North Sea pilot project produces first green hydrogen on operational platform", "src": "offshore-energy.biz", "date": "2026-07-24", "kSum": "해상풍력·수소생산·가스생산을 결합한 세계 첫 프로젝트 '포스하이돈(PosHYdon)'이 네덜란드 앞바다 에니(Eni)의 Q13a-A 플랫폼에서 첫 그린수소를 생산했다. 해상풍력 전력으로 해수를 전기분해하는 방식이며, 기존 플랫폼을 재활용했다.", "eSum": "The PosHYdon pilot, the first project combining offshore wind, hydrogen production and gas production at sea, has produced its first green hydrogen on Eni's electrified Q13a-A platform off the Dutch coast, using wind-powered electrolysis of seawater on a repurposed platform.", "kImp": "미래 선박연료 원료인 그린수소를 기존 해상 플랫폼에서 생산할 수 있음을 실증하며, 비용·통합 과제에 대한 실무 지식을 제공한다.", "eImp": "Demonstrates offshore production of green hydrogen, a key future marine-fuel feedstock, by repurposing existing platforms and informing cost and integration challenges.", "url": "https://www.offshore-energy.biz/north-sea-pilot-project-produces-first-green-hydrogen-on-operational-platform/"}, {"code": "EE", "title": "China's Largest Hydrogen-Powered Inland Cargo Ship is Launched", "src": "maritime-executive", "date": "2026-07-23", "kSum": "중국이 최대 규모의 수소연료전지 내륙 화물선 '윈타오 1호(Yun Tao No.1)'를 진수했다. CSSC와 함께 건조한 70m·140TEU·2,000t급으로, 260kW 연료전지 3기와 배터리로 항속 760km를 낸다. 주장강(Pearl River) 유역 100척 네트워크의 첫 선박으로, 디젤 대비 운항비를 20~30% 낮춘다고 한다.", "eSum": "China launched Yun Tao No.1, its largest hydrogen fuel-cell inland cargo ship (70m, 140 TEU, 2,000t) built with CSSC. Powered by three 260 kW fuel cells and batteries with a 760 km range, it is the first of a planned 100-vessel Pearl River network claimed to cut operating costs 20-30% versus diesel.", "kImp": "중국이 내륙 수소 운송을 실증에서 보조금 없는 상업 규모로 확대하려는 움직임으로, 내륙 수로의 무배출 선택지를 넓힌다.", "eImp": "Signals China's push to move inland hydrogen shipping from demonstration to subsidy-free commercial scale, expanding zero-emission options for inland waterways.", "url": "https://maritime-executive.com/article/china-s-largest-hydrogen-powered-inland-cargo-ship-is-launched"}, {"code": "EE", "title": "Data-driven decarbonisation with Bureau Veritas", "src": "seatrade-maritime", "date": "2026-07-23", "kSum": "세아트레이드(Seatrade) 팟캐스트(포시도니아 2026 녹음)에서 뷰로베리타스(Bureau Veritas)의 쥘리앵 불랑(Julien Boulland)이 선사가 GHG 규제에 대응하도록 선급이 지원하는 방법, 배출 데이터 정확성과 검증자 역할, LNG의 위치, 미래 GHG 규정 대비 등을 논의했다.", "eSum": "In a Seatrade podcast recorded at Posidonia 2026, Bureau Veritas' Julien Boulland discusses how classification supports shipowners in navigating GHG regulations, ensuring emissions-data accuracy and the verifier's role, LNG's place as a fuel, and preparing for future GHG rules.", "kImp": "EU ETS·FuelEU·IMO 조치가 강화되면서 정확하고 검증된 배출 데이터의 중요성이 커지고 있음을 강조한다.", "eImp": "Highlights the growing importance of accurate, verified emissions data as compliance under EU ETS, FuelEU and IMO measures tightens.", "url": "https://www.seatrade-maritime.com/sustainability/data-driven-decarbonisation-with-bureau-veritas"}]}, {"code": "DIG", "type": "news", "kTitle": "Section 7. 디지털라이제이션", "eTitle": "Section 7. Digitalization", "items": [{"code": "DIG", "title": "AI and tracking the dark fleet", "src": "seatrade-maritime", "date": "2026-07-30", "kSum": "세아트레이드 마리타임(Seatrade Maritime) 팟캐스트에서 푸닛 오자(Punit Oza)가 AI와 데이터 분석을 활용해 제재를 회피하는 '다크 플릿(dark fleet)'(AIS 조작·불투명 소유구조 선박)을 탐지·추적하는 방법을 다뤘다.", "eSum": "A Seatrade Maritime podcast with Punit Oza examines how AI and data analytics are being used to detect and track the 'dark' or shadow fleet, vessels evading sanctions via AIS manipulation and opaque ownership structures.", "kImp": "AI 기반 해양 인텔리전스가 제재 준수·보험·리스크 심사의 핵심 수단이 되고 있음을 보여준다.", "eImp": "Shows AI-driven maritime intelligence becoming central to sanctions compliance, insurance and risk screening.", "url": "https://www.seatrade-maritime.com/maritime-technology/ai-and-tracking-the-dark-fleet"}, {"code": "DIG", "title": "Dryad Global launches AI-assisted maritime intelligence platform", "src": "splash247", "date": "2026-07-29", "kSum": "해양 리스크 전문기업 드라이어드 글로벌(Dryad Global)이 AI 기반 인텔리전스 플랫폼 '베리헬름(Verihelm)'을 출시했다. AIS·제재 목록·뉴스·오픈소스 자동 모니터링에 분석가 검토를 결합해 사건 보고, 선박·항해 리스크 평가, 제재 스크리닝을 API로 제공한다.", "eSum": "Maritime risk firm Dryad Global launched Verihelm, an AI-assisted platform combining automated monitoring of AIS, sanctions lists, news and open sources with analyst review to deliver incident reports, vessel and voyage risk assessments, and sanctions screening via API.", "kImp": "데이터 과부하를 실행 가능한 리스크 판단으로 바꾸기 위해 AI 확장성과 인간 판단을 결합하려는 수요를 반영한다.", "eImp": "Reflects demand for combining AI scale with human judgement to turn data overload into actionable maritime risk decisions.", "url": "https://splash247.com/dryad-global-launches-ai-assisted-maritime-intelligence-platform/"}, {"code": "DIG", "title": "The hard truth about maritime autonomy", "src": "splash247", "date": "2026-07-29", "kSum": "SplashTech 기고문으로, 해양 자율운항이 과장된 기대와 달리 실무·규제·상업적 난관이 크다고 지적한다. 오션 인피니티(Ocean Infinity)의 로봇 선박 등을 예로 현실적인 도입 시점과 조건을 짚는다.", "eSum": "A SplashTech opinion piece argues that maritime autonomy faces harder practical, regulatory and commercial hurdles than the hype suggests, using examples such as Ocean Infinity's robotic vessels to weigh realistic timelines and conditions.", "kImp": "자율운항에 대한 기대를 조정하고, 상업 도입의 관건으로 규제와 신뢰성을 강조한다.", "eImp": "Tempers expectations on autonomous shipping, stressing regulation and reliability as gating factors for commercial deployment.", "url": "https://splash247.com/the-hard-truth-about-maritime-autonomy/"}, {"code": "DIG", "title": "Seatrium advances barge-based data centre design", "src": "splash247", "date": "2026-07-29", "kSum": "싱가포르 시트리움(Seatrium)이 바지선 기반(부유식) 데이터센터 설계를 진전시키고 있다. AI 수요 급증에 따른 해상 디지털 인프라 시장에 조선 역량을 활용하려는 행보다.", "eSum": "Singapore's Seatrium is advancing a barge-based (floating) data centre design, positioning its shipbuilding capabilities to serve surging AI-driven demand for offshore digital infrastructure.", "kImp": "조선과 디지털 인프라의 융합을 보여주며, AI 컴퓨팅 수요 증가로 새로운 해상 시장이 열리고 있음을 시사한다.", "eImp": "Signals convergence of shipbuilding and digital infrastructure, opening a new offshore market as AI compute demand grows.", "url": "https://splash247.com/seatrium-advances-barge-based-data-centre-design/"}, {"code": "DIG", "title": "Fugro takes stake in DTACT to deepen data intelligence push", "src": "splash247", "date": "2026-07-28", "kSum": "지오데이터 전문기업 퓨그로(Fugro)가 데이터 인텔리전스 역량 강화를 위해 DTACT의 지분을 인수했다. 지오데이터·해양 사업 전반의 분석·디지털 서비스를 확장하려는 목적이다.", "eSum": "Geo-data specialist Fugro has taken a stake in DTACT to strengthen its data-intelligence capabilities, expanding analytics and digital services across its geo-data and marine operations.", "kImp": "조사·지오데이터 기업들이 디지털 서비스로 가치사슬 상단으로 이동하기 위해 데이터 분석에 투자하고 있음을 보여준다.", "eImp": "Illustrates how survey and geo-data firms are investing in data analytics to move up the value chain toward digital services.", "url": "https://splash247.com/fugro-takes-stake-in-dtact-to-deepen-data-intelligence-push/"}, {"code": "DIG", "title": "Pindustry takes majority stake in maritime simulator VSTEP", "src": "splash247", "date": "2026-07-28", "kSum": "투자그룹 핀더스트리(Pindustry)가 네덜란드 해양 시뮬레이션 전문기업 VSTEP의 경영권 지분을 인수했다. 시뮬레이터 기반 교육과 디지털 트윈 기술 확장을 지원한다.", "eSum": "Investment group Pindustry has taken a majority stake in Dutch maritime simulation specialist VSTEP, backing growth in simulator-based training and digital-twin technologies for crews.", "kImp": "선박이 복잡한 신연료·시스템을 도입하면서 시뮬레이션 수요가 커지는 가운데, 해양 교육 기술의 통합이 진행되고 있음을 보여준다.", "eImp": "Consolidation in maritime training tech underscores rising demand for simulation as vessels adopt complex new fuels and systems.", "url": "https://splash247.com/pindustry-takes-majority-stake-in-maritime-simulator-vstep/"}, {"code": "DIG", "title": "Shipbuilding takes digital leap with virtual platform to connect entire process", "src": "offshore-energy.biz", "date": "2026-07-24", "kSum": "HD한국조선해양(HD KSOE)이 지멘스 디지털 인더스트리 소프트웨어(Siemens)와 차세대 마린 플랫폼 도입 계약을 체결했다. 설계·생산·공급망·품질관리·정비·시운전을 AI·디지털트윈 기반 3D 데이터 환경으로 통합해, 자율 제조형 '가상 조선소' 구축을 목표로 한다.", "eSum": "HD Korea Shipbuilding & Offshore Engineering (HD KSOE) signed a definitive agreement with Siemens Digital Industries Software for a next-generation marine platform integrating design, production, supply chain, QC, maintenance and sea trials into a single AI and digital-twin 3D data environment, aiming at an autonomous 'virtual shipyard.'", "kImp": "AI 기반으로 디지털 연결된 조선소의 청사진으로, 생산성·품질을 높이고 글로벌 조선 경쟁력 구도를 바꿀 수 있다.", "eImp": "A blueprint for AI-driven, digitally connected shipyards that could lift throughput and quality and reshape global shipbuilding competitiveness.", "url": "https://www.offshore-energy.biz/shipbuilding-takes-digital-leap-with-virtual-platform-to-connect-entire-process/"}, {"code": "DIG", "title": "GTMaritime brings AI inbox intelligence to shipboard email management", "src": "thedigitalship", "date": "2026-07-24", "kSum": "GTMaritime가 선박 이메일 관리에 AI 기반 '인박스 인텔리전스'를 도입한다. 자동화로 방대한 선박 통신을 우선순위화·필터링·관리해 승무원의 행정 부담을 줄인다.", "eSum": "GTMaritime is adding AI-driven 'inbox intelligence' to shipboard email management, using automation to prioritise, filter and manage the high volume of vessel communications and reduce crew administrative burden.", "kImp": "사소하지만 부담이 큰 운영 지점에 AI를 적용해, 연결된 선박에서 AI의 실질적·단기적 가치를 보여준다.", "eImp": "Applies AI to a mundane but heavy operational pain point, showing the practical, near-term value of AI aboard connected vessels.", "url": "https://thedigitalship.com/news/maritime-software/gtmaritime-brings-ai-inbox-intelligence-to-shipboard-email-management/"}, {"code": "DIG", "title": "Newport adds OneWeb to Starlink-equipped fleet", "src": "splash247", "date": "2026-07-24", "kSum": "뉴포트(Newport)가 기존 스타링크(Starlink)에 더해 유텔샛 원웹(OneWeb) 저궤도(LEO) 연결을 함대에 추가한다. 다중궤도(multi-orbit) 방식으로 고대역폭 해상통신의 회복력과 커버리지를 높인다.", "eSum": "Newport is adding Eutelsat OneWeb LEO connectivity alongside existing Starlink across its fleet, adopting a multi-orbit approach to improve the resilience and coverage of high-bandwidth maritime communications.", "kImp": "다중궤도 연결이 신뢰성 확보의 표준이 되고 있으며, 데이터 집약적 디지털·AI 서비스의 기반이 된다.", "eImp": "Multi-orbit connectivity is becoming a reliability standard, underpinning data-heavy digital and AI services at sea.", "url": "https://splash247.com/newport-adds-oneweb-to-starlink-equipped-fleet/"}]}, {"code": "TECH", "type": "news", "kTitle": "Section 8. 선박관리 기술", "eTitle": "Section 8. Ship Manager Technical", "items": [{"code": "TECH", "title": "Allseas readies overhauled Solitaire pipelayer for Gulf return", "src": "marinelink.com", "date": "2026-07-24", "kSum": "네덜란드 해양 시공사 올시즈(Allseas)가 로테르담에서 10개월에 걸쳐 파이프 부설선 솔리테어(Solitaire)의 사상 최대 규모 개조·재생 프로그램을 완료했다. 추진, 발전, 자동화, 하이브리드 동력 시스템을 현대화하고 25년 이상 사용된 더블조인트팩토리(DJF)를 업그레이드했다. 시운전 후 멕시코만 초심해 프로젝트에 투입되며 이후 서아프리카·대만·호주 2년 캠페인에 나선다.", "eSum": "Dutch offshore contractor Allseas has completed one of the most extensive renewal and upgrade programmes in the history of its pipelay vessel Solitaire, after 10 months of work in Rotterdam. The programme modernised propulsion, power generation, automation and hybrid power systems and upgraded its long-serving double joint factory (DJF). Following sea trials it returns to service in the Gulf of Mexico before a two-year campaign covering West Africa, Taiwan and Australia.", "kImp": "선박관리 기술팀 관점에서 추진·발전·자동화·하이브리드 동력을 아우르는 대규모 중년기(mid-life) 기술 개조·드라이도킹 사례로, 자산 수명 연장 및 개조 프로젝트 관리의 모범 사례를 보여준다.", "eImp": "A large-scale mid-life technical renewal spanning propulsion, power, automation and hybrid systems, offering a template for the drydock/upgrade projects that ship managers' technical teams plan and oversee.", "url": "https://www.marinelink.com/news/allseas-readies-overhauled-solitaire-541504"}, {"code": "TECH", "title": "PETRONAS agrees GTT Marine tech deal for chartered LNG fleet", "src": "smartmaritimenetwork.com", "date": "2026-07-23", "kSum": "페트로나스(PETRONAS)가 용선 LNG 선단 전반에 GTT 마린(GTT Marine)의 선박 성능 소프트웨어를 배치해 운항 효율을 높이고 연료 소모와 배출을 줄이기로 합의했다. 데이터 수집, 성능 모니터링, 항해 최적화, 화물 관리 애플리케이션이 포함되며 눈(noon) 보고서와 고주파 센서 데이터, 디지털 트윈을 결합해 성능을 관리한다. 향후 선단 확대에 대비한 연장 옵션도 포함됐다.", "eSum": "PETRONAS has agreed to deploy GTT Marine's vessel performance software across its chartered LNG carrier fleet to improve operational efficiency and cut fuel use and emissions. The suite covers data acquisition, performance monitoring, voyage optimisation and cargo management, combining noon reports with high-frequency sensor data and digital twins. The deal includes an option to extend as the chartered fleet grows.", "kImp": "선단 성능·기술관리 시스템은 CII 대응과 연료 효율 개선 등 선박관리 기술 업무의 핵심으로, 데이터 기반 기술관리 도입 흐름을 보여준다.", "eImp": "Fleet performance and technical-management systems are central to ship-manager technical work such as CII compliance and fuel-efficiency improvement, illustrating the shift to data-driven technical management.", "url": "https://smartmaritimenetwork.com/2026/07/23/petronas-agrees-gtt-marine-tech-deal-for-chartered-lng-fleet/"}, {"code": "TECH", "title": "Newport adds OneWeb to Starlink-equipped fleet", "src": "smartmaritimenetwork.com", "date": "2026-07-24", "kSum": "그리스 선박관리사 뉴포트(Newport)가 기존 스타링크(Starlink) 구축에 더해 선단 전반에 원웹(OneWeb) 연결을 추가해 다중궤도(멀티오빗) 위성 연결 체계를 완성했다. 이를 통해 회복탄력적인 상시 연결을 확보하려는 조치다.", "eSum": "Greek ship management company Newport has added OneWeb connectivity across its fleet to complement its existing Starlink deployment, building a resilient multi-orbit satellite connectivity setup. The move is aimed at maintaining reliable, always-on fleet connectivity.", "kImp": "선단 상시 연결성은 원격 상태 모니터링, 기술관리, 선원 복지를 뒷받침하는 기반으로, 선박관리 기술 운영의 디지털 인프라 강화 흐름을 보여준다.", "eImp": "Fleet-wide connectivity underpins remote condition monitoring, technical management and crew welfare, reflecting the strengthening of digital infrastructure behind ship-manager technical operations.", "url": "https://smartmaritimenetwork.com/2026/07/24/newport-adds-oneweb-to-starlink-equipped-fleet/"}]}, {"code": "HR", "type": "news", "kTitle": "Section 9. 해기인력·선원", "eTitle": "Section 9. Marine HR", "items": [{"code": "HR", "title": "INTERCARGO: Every seafarer deserves to return home", "src": "safety4sea.com", "date": "2026-07-29", "kSum": "인터카고(INTERCARGO)는 여러 전략적 해역에서 상선을 겨냥한 공격이 다시 증가함에 따라 선원과 민간 상선을 보호하기 위한 긴급 조치를 촉구했다. 단체는 모든 선원이 안전하게 귀가할 권리가 있음을 강조했다.", "eSum": "INTERCARGO has called for urgent action to protect seafarers and civilian merchant shipping following a renewed increase in attacks targeting commercial vessels across several strategic maritime regions. The association stressed that every seafarer deserves to return home safely.", "kImp": "지정학적 위험이 선원 안전·복지 문제로 직결되고 있어, 선원 보호와 귀환 보장이 해운업계 인적자원 관리의 핵심 현안으로 부상하고 있다.", "eImp": "Escalating geopolitical risk is translating directly into seafarer safety and welfare concerns, making crew protection and repatriation a central marine HR issue.", "url": "https://safety4sea.com/intercargo-every-seafarer-deserves-to-return-home/"}, {"code": "HR", "title": "7 micro-habits to help seafarers reset their minds", "src": "safety4sea.com", "date": "2026-07-23", "kSum": "해상 근무는 회복할 시간과 공간을 충분히 주지 않아 신체적·정서적 긴장이 하루 종일 쌓일 수 있다. 짧은 미세 습관(micro-habit)이 자동적 스트레스 반응을 끊고 더 신중한 대응의 여지를 만들며, 반복 시 폭넓은 웰빙 루틴의 유용한 요소가 될 수 있다.", "eSum": "Life at sea rarely leaves time or space for recovery, allowing physical and emotional tension to accumulate through the day. Small micro-habits can interrupt automatic stress reactions and, repeated consistently, become useful additions to a wider seafarer wellbeing routine.", "kImp": "저비용의 실천 가능한 자기관리 기법을 제시해 선원 스트레스 관리와 정신건강 지원의 실무적 방안을 제공한다.", "eImp": "It offers low-cost, actionable self-care techniques, giving practical tools for seafarer stress management and mental health support.", "url": "https://safety4sea.com/cm-7-micro-habits-to-help-reset-your-mind/"}, {"code": "HR", "title": "7 + 1 sources of stress affecting seafarer wellbeing", "src": "safety4sea.com", "date": "2026-07-23", "kSum": "선원의 스트레스는 명확한 단일 원인이 없는 경우가 많으며, 업무 부담·가족과의 이별·어려운 인간관계·환경 조건·신체적 피로가 동시에 쌓인다. 회복이나 지원의 시간이 제한될 때 이러한 압박은 특히 가중된다.", "eSum": "Stress for seafarers rarely has one obvious cause; work demands, family separation, difficult relationships, environmental conditions and physical exhaustion can build up simultaneously. These pressures intensify when there is limited time for recovery or support.", "kImp": "선원 웰빙을 위협하는 복합적 스트레스 요인을 체계화해, 선사가 다층적 복지·지원 체계를 설계할 필요성을 시사한다.", "eImp": "By mapping the compounding stressors on seafarer wellbeing, it signals the need for operators to design multi-layered welfare and support systems.", "url": "https://safety4sea.com/cm-7-1-sources-of-stress-affecting-seafarer-wellbeing/"}]}, {"code": "HSEQ", "type": "news", "kTitle": "Section 10. HSEQ·손해방지", "eTitle": "Section 10. HSEQ", "items": [{"code": "HSEQ", "title": "UK MAIB investigation: Fatal man overboard incident on bulk carrier", "src": "safety4sea.com", "date": "2026-07-28", "kSum": "영국 해양사고조사국(MAIB)은 2025년 10월 스웨덴 출항 후 파일럿 사다리를 준비하던 갑판장(bosun)이 벌크선 주갑판에서 바다로 추락해 사망한 사고 보고서를 발표했다. 고인은 구명동의(PFD)를 착용하지 않았고, 고장 난 파일럿 사다리 대빗을 수동으로 다루던 관행과 개방된 현측 난간 구역에서의 PPE 미착용 등 SMS 위험완화 조치가 지켜지지 않았다.", "eSum": "The UK MAIB published its report into the fatal fall of a bosun from a bulk carrier's main deck during pilot ladder preparations off Sweden in October 2025. The crew had become normalised to manually handling the ladder with an out-of-service davit, and the SMS-required harness and PFD were not used near the open shipside railing.", "kImp": "갑판 가장자리 작업 시 PFD·안전벨트 착용, SMS 준수, 위험구역 표시의 중요성을 재확인시킨다.", "eImp": "Reinforces the need for PFD/harness use, SMS compliance and hazard-area marking during work near unguarded deck edges.", "url": "https://safety4sea.com/uk-maib-investigation-fatal-man-overboard-incident-on-bulk-carrier/"}, {"code": "HSEQ", "title": "Vessel collision damages crane and spills plastic pellets into River Tyne", "src": "safety4sea.com", "date": "2026-07-28", "kSum": "타인 항(Port of Tyne)에서 해상풍력 지원선 윈드 오르카(Wind Orca)가 출항 중 접안해 있던 컨테이너선 BG 오렌지(BG Orange)와 충돌해 갠트리 크레인이 크게 손상되고 컨테이너에서 플라스틱 수지 펠릿(너들)이 타인강으로 유출됐다. 1명이 비치명적 부상으로 병원에 이송됐으며, 항만은 오일펜스와 회수장비를 투입해 대규모 방제 작업을 벌였다.", "eSum": "At the Port of Tyne, the offshore vessel Wind Orca collided with the berthed container ship BG Orange while departing, damaging a gantry crane and spilling plastic resin pellets (nurdles) into the River Tyne. One person was hospitalised with non-life-threatening injuries, and the port deployed booms and recovery equipment for an extensive clean-up.", "kImp": "항내 이·접안 조선 리스크와 펠릿 유출에 따른 환경 방제·야생동물 피해 대응의 중요성을 부각한다.", "eImp": "Highlights port manoeuvring collision risk and the environmental clean-up burden from nurdle spills.", "url": "https://safety4sea.com/vessel-collision-damages-crane-and-spills-plastic-pellets-into-river-tyne/"}, {"code": "HSEQ", "title": "Tugboat captain pleads guilty over collision that killed three children", "src": "safety4sea.com", "date": "2026-07-28", "kSum": "미국 마이애미 비스케인 만(Biscayne Bay)에서 전방 시야가 가려진 바지선을 견시원 없이 운항하다 범선을 들이받아 세일링 캠프 어린이 3명을 숨지게 한 예인선 선장이 연방 선원 과실치사 혐의에 대해 유죄를 인정했다. 갑판실과 크레인에 전방 시야가 막혀 있었고 견시원이 배치되지 않았으며, 선장은 운항 중 휴대전화를 사용한 것으로 조사됐다.", "eSum": "A tugboat captain pleaded guilty to federal seaman's manslaughter after pushing a barge with visibility obstructed by a deckhouse and crane, without a lookout, causing a fatal collision in Biscayne Bay, Miami that killed three children. Investigators found the operator had also been using a cellphone while underway.", "kImp": "견시 배치와 주의의무 준수의 중요성, 시야 제한 작업에서 안전관리 실패에 따르는 형사책임을 보여준다.", "eImp": "Underscores lookout duties and the criminal liability arising from failed safety management during restricted-visibility operations.", "url": "https://safety4sea.com/tugboat-captain-pleads-guilty-over-collision-that-killed-three-children/"}, {"code": "HSEQ", "title": "BSU investigation: Uncontrolled rescue boat descent during drill", "src": "safety4sea.com", "date": "2026-07-23", "kSum": "독일 연방해양사고조사국(BSU)은 2023년 6월 피레아스 앞바다에 정박 중이던 탱커에서 훈련 도중 윈치 결함으로 구조정이 약 10m 높이에서 통제불능으로 하강한 사고 보고서를 발표했다. 승정한 3명이 탑승한 상태에서, 원격 제어로 유압 윈치 브레이크를 풀면서 하강이 시작됐다.", "eSum": "The German BSU published its report into an incident off Piraeus in June 2023 in which a rescue boat carrying three crew descended uncontrollably from about ten metres during a drill due to a winch defect. The lowering began after the boat crew released the hydraulic winch brake by remote control.", "kImp": "구조정 대빗 윈치 정비와 진수 훈련 중 낙하 위험 관리의 필요성을 상기시킨다.", "eImp": "Reminds operators to maintain rescue boat davit winches and manage fall risks during launching drills.", "url": "https://safety4sea.com/bsu-investigation-uncontrolled-rescue-boat-descent-during-drill/"}, {"code": "HSEQ", "title": "TAIC investigation: Pump failure triggers toxic gas incident", "src": "safety4sea.com", "date": "2026-07-23", "kSum": "뉴질랜드 교통사고조사위원회(TAIC)는 2025년 2월 건선거 정비 중 오염수가 밀폐된 선수 스러스터실로 잘못 유입돼 근로자들이 유독성 황화수소(H2S)에 노출된 사고 보고서를 발표했다. 실습 정비사 2명이 대피했으나 감독자 1명이 잠시 가스에 노출됐고, 기관장과 2등기관사는 진입했다가 쓰러졌다.", "eSum": "New Zealand's TAIC reported on a February 2025 incident in which contaminated water was accidentally pumped into a confined bow thruster room during dry-dock maintenance, exposing workers to toxic hydrogen sulphide (H2S). Two apprentice fitters escaped, a supervisor was briefly overcome, and the chief and second engineers collapsed after entering.", "kImp": "밀폐구역 대기 측정과 진입 통제, 우발적 오염수 유입 같은 확인되지 않은 위험에 대한 경계를 강조한다.", "eImp": "Stresses enclosed space atmosphere testing, entry controls and vigilance against unrecognised hazards such as accidental contaminant ingress.", "url": "https://safety4sea.com/taic-investigation-pump-failure-triggers-toxic-gas-incident/"}]}, {"code": "KR", "type": "news", "kTitle": "Section 11. 한국 해운시장", "eTitle": "Section 11. Korean Shipping Market", "items": [{"code": "KR", "title": "HD한국조선해양, 상반기 수주 163억달러…연간 목표 96% 달성", "src": "뉴스핌(Newspim)", "date": "2026-07-29", "kSum": "HD한국조선해양(HD KSOE)은 7월29일 2026년 2분기 실적 컨퍼런스콜에서 조선 계열사들이 상반기에 163억8000만달러를 수주해 연간 목표의 96.2%를 채웠다고 밝혔다. HD현대중공업은 상반기에만 연간 수주목표를 초과 달성했다. 선종별로는 초대형가스운반선(VLGC) 38척, LNG운반선 17척, FSRU 1척과 초대형원유운반선(VLCC)·수에즈막스 탱커 등 고부가 선종이 중심이었다. 2분기 영업이익은 1조6000억원을 넘었고 매출은 8조9270억원으로 전년 대비 각각 20.2%, 72.5% 증가했다.", "eSum": "On 29 July HD Korea Shipbuilding & Offshore Engineering (HD KSOE) said in its Q2 2026 earnings call that its shipbuilding units booked USD16.38bn of orders in H1, reaching 96.2% of the full-year target, with HD Hyundai Heavy Industries alone already exceeding its annual goal. The order mix was led by high-value tonnage - 38 VLGCs, 17 LNG carriers, one FSRU plus VLCCs and Suezmax tankers. Q2 operating profit topped KRW1.6tn and revenue reached KRW8.927tn, up 20.2% and 72.5% year on year.", "kImp": "조선 빅3의 고부가 선종 중심 수주 호조와 실적 턴어라운드를 보여주는 지표로, 국내 조선업 장기 호황 진입과 HMM 등 해운·조선 밸류체인 전반의 투자심리에 긍정적이다.", "eImp": "A clear marker of the Korean big-three yards' high-value order momentum and earnings turnaround, reinforcing the view of a structural upcycle and supporting sentiment across the wider Korean shipping-shipbuilding value chain.", "url": "https://www.newspim.com/news/view/20260729000966"}, {"code": "KR", "title": "HD한국조선해양, 해상 데이터센터·美 함정 수주 '속도'", "src": "뉴스핌(Newspim)", "date": "2026-07-29", "kSum": "HD한국조선해양은 7월29일 2분기 실적 발표와 함께 신사업 확대 전략을 제시했다. 부유식 해상 데이터센터와 미국 함정(MRO·건조) 시장 진출에 속도를 내고 있으며, 하반기 글로벌 함정 수주가 가시권에 들어왔다고 밝혔다. 상선 부문의 고선가 계약이 실적으로 반영되는 가운데, 방산·해양·데이터센터 등 비상선 부문으로 포트폴리오를 다각화해 중장기 성장동력을 확보한다는 구상이다.", "eSum": "Alongside its Q2 results on 29 July, HD KSOE laid out an expansion into new segments, saying it is accelerating into floating offshore data centres and the US naval (newbuild and MRO) market, with global warship orders now within sight in the second half. As high-priced commercial newbuild contracts feed into earnings, the group aims to diversify beyond merchant tonnage into defence, offshore and data-centre projects for medium-term growth.", "kImp": "국내 조선사가 상선 호황을 넘어 함정·해양·데이터센터 등 고부가 비상선 영역으로 확장하는 흐름을 보여주며, 한·미 조선협력(MASGA) 및 방산 수출 확대 기대와 맞물린다.", "eImp": "Signals Korean yards pushing beyond the merchant boom into higher-margin naval, offshore and data-centre work, dovetailing with expectations around Korea-US shipbuilding cooperation and defence exports.", "url": "https://www.newspim.com/news/view/20260729001080"}, {"code": "KR", "title": "HMM, 美 서안 '컨' 터미널 처리능력 年 88만TEU로 확대", "src": "코리아쉬핑가제트(KSG)", "date": "2026-07-27", "kSum": "HMM이 운영하는 미국 서안 터미널 워싱턴유나이티드터미널(WUT·터코마항)이 HD현대삼호와 항만크레인 4기 공급계약을 체결했다. 노후 안벽크레인 2기를 신규 장비로 교체하고 야드크레인 2기를 추가해 연간 하역능력을 59만TEU에서 88만TEU로 확대한다. HD현대삼호가 설계·제작·운송·설치·시운전을 턴키로 수행해 2028년까지 완료할 예정이다. HMM은 인도 JNPA·바드반, 스페인 알헤시라스 TTIA 등 해외 항만 인프라 투자도 이어가고 있다.", "eSum": "HMM's US West Coast terminal, Washington United Terminal (WUT) at Tacoma, has signed a contract with HD Hyundai Samho for four port cranes, replacing two ageing ship-to-shore cranes and adding two yard cranes to lift annual throughput capacity from 590,000 TEU to 880,000 TEU. HD Hyundai Samho will deliver the cranes on a turnkey basis by 2028. HMM continues to invest in overseas port infrastructure, including India's JNPA/Vadhvan and TTIA at Algeciras, Spain.", "kImp": "HMM이 선대 확장과 함께 미주 서안 핵심 항만 인프라를 현대화해 네트워크 경쟁력을 강화하는 흐름으로, 국산 항만장비(HD현대삼호) 수요 확대 측면도 있다.", "eImp": "Shows HMM pairing fleet growth with modernisation of key US West Coast port assets, strengthening network competitiveness while also supporting demand for Korean-made port equipment.", "url": "https://www.ksg.co.kr/news/main_newsView.jsp?pNum=147693"}, {"code": "KR", "title": "삼성중공업, 2분기 영업익 3250억…전년比 대폭 증가", "src": "코리아쉬핑가제트(KSG)", "date": "2026-07-24", "kSum": "삼성중공업은 2026년 2분기 매출 3조2307억원, 영업이익 3250억원, 순이익 2228억원을 거뒀다고 7월24일 밝혔다. 영업이익은 전년 동기 대비 크게 늘었다. 글로벌 오퍼레이터 대상 고부가 선종(LNG운반선·FLNG 등) 중심의 수주 잔고가 실적으로 반영되며 수익성이 개선됐다.", "eSum": "Samsung Heavy Industries reported Q2 2026 revenue of KRW3.2307tn, operating profit of KRW3.25bn (KRW325bn) and net profit of KRW222.8bn on 24 July, with operating profit sharply higher year on year. Profitability improved as its backlog of high-value tonnage - LNG carriers and FLNG for global operators - converted into earnings.", "kImp": "조선 빅3의 실적 개선세를 확인시키는 지표로, 과거 저가 수주 해소와 고선가 계약 반영이라는 업계 전반의 턴어라운드 국면을 뒷받침한다.", "eImp": "Confirms the earnings recovery across the big-three yards, underpinning the industry-wide turnaround as legacy low-priced orders clear and high-priced contracts flow through.", "url": "https://www.ksg.co.kr/news/main_newsView.jsp?pNum=147679"}, {"code": "KR", "title": "광양항 완전자동화 테스트베드 착공…2029년 준공 목표", "src": "코리아쉬핑가제트(KSG)", "date": "2026-07-30", "kSum": "해양수산부와 여수광양항만공사(YGPA)는 7월30일 광양항에서 '항만자동화 테스트베드 구축사업' 착공식을 열었다. 국산 하역장비와 인공지능(AI) 기술을 적용한 완전자동화 컨테이너부두를 조성하는 사업으로, 국내 기술 기반의 자동화 항만 상용화를 검증하는 것이 목표다. 정부는 이를 통해 국산 항만장비 산업 육성과 부산항 등 후속 자동화 확산의 발판을 마련한다는 구상이다.", "eSum": "The Ministry of Oceans and Fisheries and Yeosu Gwangyang Port Authority (YGPA) held a groundbreaking on 30 July for a port-automation testbed at Gwangyang, building a fully automated container terminal using domestically developed handling equipment and AI. The aim is to validate homegrown automation technology for commercialisation, fostering a Korean port-equipment industry and paving the way for wider rollout at Busan and other ports.", "kImp": "국산 기술 기반 완전자동화 항만의 실증 무대로, 해수부 스마트항만 정책과 국내 항만장비 국산화 전략의 핵심 프로젝트다.", "eImp": "A flagship proving ground for Korea's smart-port policy and localisation of port equipment, central to the ministry's push to reduce reliance on foreign automation technology.", "url": "https://www.ksg.co.kr/news/main_newsView.jsp?pNum=147733"}, {"code": "KR", "title": "친환경인증선박 보급지원 참여선사 모집…선가 지원비율 최대 30%로 상향", "src": "머니투데이", "date": "2026-07-26", "kSum": "해양수산부는 국내 중소형 연안선사의 친환경선박 건조를 돕는 '친환경인증선박 보급지원사업' 참여 선사를 7월27일부터 10월30일까지 모집한다. 건조비의 최대 30%를 지원하는데, 올해부터 선사의 초기 투자부담을 줄이기 위해 지원비율을 기존 선가의 10%에서 30%로 대폭 상향했다. 지원 한도는 척당 최대 35억원이며, LNG·전기·하이브리드 등 3등급 이상 친환경인증 선박이 대상이다. 취득 시 최대 2%포인트 취득세 경감 혜택도 제공한다.", "eSum": "The Ministry of Oceans and Fisheries is recruiting shipping companies for its eco-certified vessel support scheme from 27 July to 30 October, funding up to 30% of newbuild cost for small and mid-sized coastal operators. This year the maximum subsidy rate was raised sharply from 10% to 30% of ship price to ease upfront investment, capped at KRW3.5bn per ship, for grade-3-or-higher eco-certified vessels using LNG, electric or hybrid propulsion, plus an acquisition-tax cut of up to 2 percentage points.", "kImp": "연안해운 탈탄소화를 위한 핵심 재정지원 정책으로, 지원비율 3배 상향은 친환경선박 발주 수요를 자극하고 국내 조선·기자재 생태계에도 파급된다.", "eImp": "A key funding lever for coastal-shipping decarbonisation; tripling the subsidy rate is likely to stimulate green newbuild demand and ripple into the domestic yard and equipment supply chain.", "url": "https://www.mt.co.kr/economy/2026/07/26/2026072614232374124"}, {"code": "KR", "title": "중동항로/ 정세불안 재확대…한국발 운임 7200달러 돌파", "src": "코리아쉬핑가제트(KSG)", "date": "2026-07-28", "kSum": "미국-이란 무력충돌 재개로 중동항로가 다시 위험국면에 접어들었다. 이란은 7월11일 호르무즈 인근에서 UAE 선사 GFS의 컨테이너선을 공격했고, 후티 반군은 7월20일 바브엘만데브 봉쇄를 선언했다. 한국해양진흥공사(KCCI) 기준 부산발 중동행 운임은 7월20일 FEU당 7269달러로 역대 최고치를 경신했고 7월 평균 7233달러로 전월비 14% 올랐다. CMA CGM은 8월1일부터 긴급유류할증료를 부과하기로 했으며, 선사들은 노선 재조정과 추가 운임인상을 검토 중이다.", "eSum": "Renewed US-Iran hostilities have pushed the Middle East trade back into a danger phase. Iran attacked a UAE carrier GFS boxship near Hormuz on 11 July and the Houthis declared a Bab-el-Mandeb blockade on 20 July. Busan-to-Middle East rates (KCCI) hit a record USD7,269/FEU on 20 July, averaging USD7,233 in July, up 14% month on month. CMA CGM will levy an emergency bunker surcharge from 1 August, and carriers are weighing route changes and further rate hikes.", "kImp": "지정학 리스크가 한국발 컨테이너 운임과 전쟁위험보험료를 동시에 밀어올리는 국면으로, 수출입 물류비와 국적선사 수익성에 직접 영향을 준다.", "eImp": "Geopolitical risk is simultaneously lifting Korea-origin container rates and war-risk premiums, feeding directly into export logistics costs and national carriers' margins.", "url": "https://www.ksg.co.kr/news/main_newsView.jsp?pNum=147685"}, {"code": "KR", "title": "벌크선 시장, 대형선 선방에도 중소형선 부진…BDI 2664", "src": "코리아쉬핑가제트(KSG)", "date": "2026-07-29", "kSum": "7월 하순 벌크선 시장은 선형별로 시황이 엇갈렸다. 7월28일 건화물선운임지수(BDI)는 2664, 한국형 지수 KDCI는 2만5424를 기록했다. 케이프선은 철광석·보크사이트 물량 증가와 태평양 수역 강세로 반등해 BCI 4140포인트·평균 용선료 4만1049달러를 기록했다. 반면 파나막스(BPI 1988·1만8832달러)는 곡물·석탄 수요 둔화와 선복 증가로 하락했고, 수프라막스(BSI 1648·2만108달러)도 대부분 항로에서 약보합세를 보였다. 한국해양진흥공사는 8월 초 상승폭은 제한적일 것으로 전망했다.", "eSum": "In late July the dry-bulk market split by segment. On 28 July the Baltic Dry Index stood at 2,664 and Korea's KDCI at 25,424. Capes rebounded on rising iron-ore and bauxite volumes and Pacific strength, with the BCI at 4,140 and average hire of USD41,049/day. Panamaxes (BPI 1,988; USD18,832) fell on softer grain and coal demand and more open tonnage, while Supramaxes (BSI 1,648; USD20,108) were mostly flat-to-soft. KOBC expects only limited upside in early August.", "kImp": "대한해운·팬오션 등 국적 벌크선사 수익과 직결되는 시황 지표로, 대형선 강세와 중소형선 부진의 양극화가 하반기 실적 변수로 작용한다.", "eImp": "A market gauge directly tied to Korean bulk operators such as Korea Line and Pan Ocean; the split between firm capes and weak mid-size tonnage is a key swing factor for H2 earnings.", "url": "https://www.ksg.co.kr/news/main_newsView.jsp?pNum=147725"}, {"code": "KR", "title": "KMI, 해운 연구기능 통합…'해운정책·산업연구실' 신설", "src": "코리아쉬핑가제트(KSG)", "date": "2026-07-30", "kSum": "한국해양수산개발원(KMI)은 해운 분야 연구역량을 통합하고 정책 대응력을 강화하기 위해 기존 해운물류·해사정책연구실과 해운산업연구실을 합친 '해운정책·산업연구실'을 신설한다고 밝혔다. 해운정책과 산업연구 기능을 한데 모아 해양수산부의 해운정책 수립을 지원하고 급변하는 시장·규제 환경에 대한 대응력을 높인다는 취지다.", "eSum": "The Korea Maritime Institute (KMI) said it is creating a new 'Shipping Policy and Industry Research Department' by merging its former shipping-logistics/maritime-policy and shipping-industry research units, consolidating policy and industry research to better support the Ministry of Oceans and Fisheries' shipping policymaking and sharpen responsiveness to fast-changing market and regulatory conditions.", "kImp": "국책연구기관의 해운 연구 조직 개편으로, 해수부 해운정책 수립의 싱크탱크 기능 강화와 정책 대응력 제고를 시사한다.", "eImp": "An organisational revamp at the state think-tank that signals a stronger analytical backbone for the ministry's shipping policy and quicker policy responses.", "url": "https://www.ksg.co.kr/news/main_newsView.jsp?pNum=147732"}]}, {"code": "INS", "type": "news", "kTitle": "Section 12. 해상보험 (H&M)", "eTitle": "Section 12. Marine Insurance (H&M)", "items": [{"code": "INS", "title": "노르웨이 앞바다 화학제품운반선서 폭발·화재 발생", "src": "Insurance Marine News", "date": "2026-07-30", "kSum": "케미컬·석유제품운반선 베르그스트라움(Bergstraum, IMO 9108740)에서 7월28일 폭발에 이어 화재가 발생했다. 사고 당시 선박은 노르웨이 남동부 프레드릭스타드(Fredrikstad) 인근 해상에 정박(투묘) 중이었다. 해상보험 전문매체 Insurance Marine News가 사고를 전하며 선체·기관(H&M) 손상과 후속 클레임 가능성이 주목된다.", "eSum": "The chemical/oil-products tanker Bergstraum (IMO 9108740) suffered an explosion followed by a fire on 28 July while at anchor off Fredrikstad in south-eastern Norway, as reported by Insurance Marine News. The casualty puts hull-and-machinery damage and a potential H&M claim in focus.", "kImp": "탱커 폭발·화재는 전형적인 H&M 대형 손해 및 오염책임 사고로, 케미컬 탱커 세그먼트의 언더라이팅 리스크와 손해율에 직접 영향을 준다.", "eImp": "A tanker explosion/fire is a classic large H&M and pollution-liability exposure, feeding directly into underwriting risk and loss ratios for the chemical-tanker segment.", "url": "https://insurancemarinenews.com/insurance-marine-news/explosion-and-fire-reported-aboard-chemical-tanker-off-south-east-norway/"}, {"code": "INS", "title": "지원선 'Skandi Amazonas', 좌초 후 추정전손(CTL) 선언", "src": "Insurance Marine News", "date": "2026-07-30", "kSum": "노르웨이 DOF그룹은 지원선(서플라이 베셀) 스칸디 아마조나스(Skandi Amazonas, IMO 9528328)가 좌초 사고 이후 복구 불가로 판단돼 추정전손(CTL)으로 선언했다고 밝혔다. CTL 선언은 선체보험자에게 전손 정산 의무를 발생시키며, 오프쇼어 지원선 부문의 보험 손해로 이어진다.", "eSum": "Norway's DOF Group has declared the offshore supply vessel Skandi Amazonas (IMO 9528328) a constructive total loss (CTL) following its grounding. A CTL declaration triggers a total-loss settlement obligation for hull underwriters and crystallises a marine insurance loss in the offshore support-vessel segment.", "kImp": "CTL 선언은 선체보험자의 전손 지급으로 직결되며, 오프쇼어 지원선 시장의 선체 언더라이팅 손익에 영향을 주는 확정적 손해 사례다.", "eImp": "A CTL declaration converts directly into a total-loss payout for hull insurers, a crystallised loss that weighs on hull underwriting results in the offshore support-vessel market.", "url": "https://insurancemarinenews.com/insurance-marine-news/skandi-amazonas-declared-a-ctl/"}, {"code": "INS", "title": "호르무즈 해협 통항량 여전히 저조", "src": "Insurance Marine News", "date": "2026-07-30", "kSum": "7월28일(화) 호르무즈 해협 통항 활동이 여전히 위축된 상태로 나타났다. Kpler 데이터에 따르면 당일 해협을 통과한 상선은 5척에 그쳤다. 통항 급감은 전쟁위험 프리미엄 상승, 사전통지 요건 강화, 항해별 심사 등 언더라이팅 강화 흐름과 맞물려 있다.", "eSum": "Traffic through the Strait of Hormuz remained subdued on Tuesday 28 July, with Kpler data showing only five commodity vessels transiting the strait that day. The sharp drop coincides with elevated war-risk premiums, tighter prior-notification requirements and voyage-by-voyage underwriting scrutiny.", "kImp": "호르무즈 통항 위축은 전쟁위험 보험시장의 수요·요율 동학을 보여주는 핵심 지표로, H&M 전쟁위험 및 화물보험 언더라이팅에 직접적 시사점을 준다.", "eImp": "Reduced Hormuz transits is a bellwether for war-risk demand and pricing dynamics, with direct implications for hull war-risk and cargo underwriting.", "url": "https://insurancemarinenews.com/insurance-marine-news/hormuz-traffic-remains-limited/"}, {"code": "INS", "title": "후티, 네 번째 사우디 유조선 공격 주장", "src": "Insurance Marine News", "date": "2026-07-30", "kSum": "예멘 후티 반군은 7월28일(화) 사우디 항만 봉쇄 선언 이후 네 번째 사우디 유조선을 공격했다고 주장했다. 피격 대상은 NCC Ghazal(IMO 9685205)로, 홍해·바브엘만데브 일대 상선에 대한 위협이 지속되고 있다. 이는 전쟁위험 보험료 급등과 항로 재조정을 부추기는 요인이다.", "eSum": "The Houthis said on Tuesday 28 July that they had attacked a fourth Saudi tanker following their announced blockade of Saudi ports, striking the NCC Ghazal (IMO 9685205). The continued threat to merchant shipping around the Red Sea and Bab-el-Mandeb is fuelling surging war-risk premiums and route diversions.", "kImp": "실제 상선 피격은 전쟁위험보험 요율과 담보 조건을 즉각 끌어올리는 트리거로, 중동·홍해 항로 화물·선체 언더라이팅의 핵심 변수다.", "eImp": "Actual attacks on merchant vessels are an immediate trigger for higher war-risk rates and tighter terms, a central driver for cargo and hull underwriting on Middle East/Red Sea routes.", "url": "https://insurancemarinenews.com/insurance-marine-news/houthis-claim-attack-on-fourth-saudi-oil-tanker/"}, {"code": "INS", "title": "우크라이나, 벌크선 'Golden Leo' 침몰 후 항만 보안 강화", "src": "Insurance Marine News", "date": "2026-07-30", "kSum": "우크라이나 당국은 벌크선 골든 레오(Golden Leo, IMO 9181833)가 7월26일(일) 침몰한 이후 항만 보안 강화를 조율하고 있다. 해당 선박은 피격 1주일 만에 침몰했다. 흑해 항만·선박에 대한 위협이 계속되면서 전쟁위험 담보와 요율에 대한 부담이 커지고 있다.", "eSum": "Ukrainian authorities are coordinating heightened security following the sinking of the bulk carrier Golden Leo (IMO 9181833) on Sunday 26 July, a week after it had been struck. Continuing threats to Black Sea ports and vessels are adding pressure on war-risk cover and pricing.", "kImp": "흑해 선박 침몰은 전쟁위험 손해의 현실화 사례로, 곡물 등 흑해 화물·선체보험 언더라이팅의 리스크 평가에 직접 반영된다.", "eImp": "The sinking of a Black Sea vessel is a realised war-risk loss that feeds directly into risk assessment for grain-and-bulk cargo and hull underwriting in the region.", "url": "https://insurancemarinenews.com/insurance-marine-news/ukraine-increases-port-security/"}, {"code": "INS", "title": "노보로시스크, 며칠간 중단됐던 원유 선적 재개", "src": "Insurance Marine News", "date": "2026-07-30", "kSum": "흑해 최대 러시아 원유수출항 노보로시스크(Novorossiysk)가 악천후와 드론 위협에 따른 며칠간의 차질 끝에 원유 선적을 재개했다. 흑해 지역의 물류·보안 불확실성이 이어지며 화물·선체 전쟁위험보험 리스크 프로파일이 변동성을 보이고 있다.", "eSum": "Russia's main Black Sea crude-oil port, Novorossiysk, has resumed crude loadings after several days of disruption caused by bad weather and increased drone activity. Persistent logistics and security uncertainty in the Black Sea is keeping the risk profile for cargo and hull war-risk cover volatile.", "kImp": "핵심 원유 수출항의 간헐적 중단·재개는 화물보험 및 전쟁위험 담보의 항해 리스크 평가와 요율 산정에 영향을 준다.", "eImp": "Intermittent stoppage and restart at a key crude export port affect voyage-risk assessment and pricing for cargo insurance and war-risk cover.", "url": "https://insurancemarinenews.com/insurance-marine-news/novorossiysk-resumes-crude-oil-loading/"}, {"code": "INS", "title": "러시아 흑해 3개 터미널, 육상운송 곡물 반입 제한", "src": "Insurance Marine News", "date": "2026-07-30", "kSum": "로이터를 인용한 보도에 따르면, 흑해 러시아 선박에 대한 위험 고조로 3개 터미널이 도로·철도를 통한 곡물 반입량을 제한하고 있다. 곡물 물류 차질은 화물보험의 담보 조건과 지연·훼손 리스크 평가에 영향을 미친다.", "eSum": "Risks to Russian shipping in the Black Sea have led three terminals to limit the amount of grain brought in by road and rail, according to a report citing Reuters. Disruption to grain logistics affects cargo-insurance terms and the assessment of delay and damage risk.", "kImp": "곡물 반입 제한은 흑해 화물보험의 공급망·전쟁위험 노출을 반영하며, 화물 언더라이팅 조건 강화 요인으로 작용한다.", "eImp": "Curbs on grain intake reflect supply-chain and war-risk exposure for Black Sea cargo insurance and can tighten cargo underwriting terms.", "url": "https://insurancemarinenews.com/insurance-marine-news/three-russian-black-sea-terminals-restrict-grain-intake-by-truck-report/"}, {"code": "INS", "title": "세인트키츠네비스 선적, 흑해 보안사고에 '깊은 우려' 표명", "src": "Insurance Marine News", "date": "2026-07-30", "kSum": "세인트키츠네비스 국제선박등록처(SKANReg)는 흑해에서 운항 중인 상선과 관련된 세 건의 개별 보안사고에 대해 '깊은 우려'를 표명했다. 기국(旗國) 차원의 경고는 해당 수역 운항 선박의 전쟁위험 노출과 보험 담보 조건 논의에 무게를 더한다.", "eSum": "The Saint Kitts and Nevis International Ship Registry (SKANReg) has expressed profound concern over three separate security incidents involving merchant vessels operating in the Black Sea. A flag-state warning adds weight to discussions of war-risk exposure and cover terms for vessels trading in the area.", "kImp": "기국의 공식 우려 표명은 흑해 운항 선박의 리스크 인식을 높여 전쟁위험·화물보험 언더라이팅의 심사 강화로 이어질 수 있다.", "eImp": "A formal flag-state warning raises perceived risk for Black Sea trading and can prompt tighter scrutiny in war-risk and cargo underwriting.", "url": "https://insurancemarinenews.com/insurance-marine-news/saint-kitts-and-nevis-expresses-concern-at-black-sea-security-incidents/"}, {"code": "INS", "title": "HFW '숫자로 보는 해사중재'…런던 반등, 싱가포르·홍콩 성장세 유지", "src": "Insurance Marine News", "date": "2026-07-30", "kSum": "로펌 HFW가 발간한 제7판 '숫자로 보는 해사중재(Maritime Arbitration in Numbers)'는 런던이 반등하고 싱가포르·홍콩이 성장 모멘텀을 유지하는 비교 통계를 제시했다. 해사중재는 선체·화물 보험 분쟁 및 클레임 해결의 주요 창구로, 보험시장의 분쟁 처리 동향을 가늠하는 지표가 된다.", "eSum": "The seventh edition of law firm HFW's 'Maritime Arbitration in Numbers: London Rebounds as Singapore and Hong Kong Maintain Momentum' provides comparative statistics on the leading maritime arbitration seats. Maritime arbitration is a key venue for hull and cargo insurance disputes and claims resolution, offering a read on dispute-handling trends in the marine market.", "kImp": "해사중재 지형 변화는 선체·화물 보험 클레임과 회수 전략, 준거법·중재지 선택에 직접 영향을 주는 실무 지표다.", "eImp": "Shifts in the arbitration landscape directly affect hull and cargo claims handling, recovery strategy and choice of law/seat - a practical bellwether for marine insurers.", "url": "https://insurancemarinenews.com/insurance-marine-news/maritime-arbitration-in-numbers-london-rebounds-as-singapore-and-hong-kong-maintain-momentum/"}]}, {"code": "PNI", "type": "news", "kTitle": "Section 13. P&I 클럽", "eTitle": "Section 13. P&I Clubs", "items": [{"code": "PNI", "title": "英 웨스트오브잉글랜드 P&I, S&P 신용등급 A-(안정적) 취득…보험료 6600억 전망", "src": "코리아쉬핑가제트(KSG)", "date": "2026-07-27", "kSum": "영국 선주상호보험조합 웨스트오브잉글랜드(West of England) P&I가 S&P글로벌로부터 신용등급 A-(안정적)를 받았다. S&P는 웨스트가 최근 수년간 국제그룹(IG) 평균을 웃도는 재무성과를 유지하고 적정성 기준을 충족하는 자본 잉여금을 확보했다고 평가했다. 2월 기준 비상준비금(free reserve)은 23% 급증한 3억7680만달러로 사상 최고치, 지급여력비율(SCR)은 195%다. 조합은 2027 회계연도(2027년 2월20일 마감) 총보험료 수입이 10% 늘어난 4억5000만달러(약 6600억원)에 이를 것으로 전망했다.", "eSum": "West of England P&I has been assigned an A- (stable) financial-strength rating by S&P Global, which noted the club has outperformed the International Group (IG) average for several years and holds capital surplus meeting its adequacy threshold. As of February, free reserves jumped 23% to a record USD376.8m and its solvency coverage (SCR) stood at 195%. The club forecasts gross premium of about USD450m for the 2027 policy year (ending 20 February 2027), up 10%.", "kImp": "IG 소속 P&I 클럽의 재무건전성 개선과 등급 상향은 선주 상호보험 시장의 자본 여력과 요율·환급 정책에 영향을 주는 신호로, 국내 선사의 클럽 선택·비용에도 시사점이 있다.", "eImp": "An upgrade and improving capital position at an IG club is a signal for mutual-market strength and pricing/return policy, with relevance to Korean owners' club selection and cost.", "url": "https://www.ksg.co.kr/news/main_newsView.jsp?pNum=147702"}, {"code": "PNI", "title": "UK P&I, 인도 위성전화·위성통신장비 규제 관련 회원 안내", "src": "UK P&I Club", "date": "2026-07-30", "kSum": "UK P&I 클럽은 7월30일 인도의 위성전화 및 위성통신장비 반입·사용 제한에 관한 회원 안내를 게시했다. 인도 항만 입출항 선박이 관련 장비 규제를 위반할 경우 억류·벌금 등 리스크가 있어, 클럽은 회원 선박에 사전 신고·허가 절차 준수를 권고하는 로스프리벤션 정보를 제공했다.", "eSum": "On 30 July UK P&I Club issued member guidance on India's restrictions covering satellite phones and satellite communication equipment. Vessels calling at Indian ports face detention or fines if they breach the rules, and the club provided loss-prevention advice urging members to comply with prior-declaration and permit requirements.", "kImp": "기항국 규제 위반은 선박 억류·과징금 등 P&I 클레임으로 이어질 수 있어, 클럽의 사전 안내는 회원 선박의 인도 항로 운항 리스크 관리에 실질적으로 중요하다.", "eImp": "Breaches of port-state rules can lead to detentions and fines that become P&I claims, so the club's advisory is materially useful for members managing India-trade risk.", "url": "https://www.ukpandi.com/news-and-resources/news/article/india-restrictions-on-satellite-phones-and-satellite-communication-equipment/"}, {"code": "PNI", "title": "UK P&I, 암모니아 대체연료 유출 대응 고려사항 안내", "src": "UK P&I Club", "date": "2026-07-28", "kSum": "UK P&I 클럽은 7월28일 암모니아를 연료로 사용하는 선박의 유출(스필) 대응 고려사항을 다룬 로스프리벤션 자료를 게시했다. 독성·부식성이 강한 암모니아의 특성상 유출 시 인명·환경 피해가 크며, 클럽은 대응 절차, 개인보호장비, 비상계획 등 회원 선박이 준비해야 할 사항을 정리했다.", "eSum": "On 28 July UK P&I Club published loss-prevention material on spill-response considerations for ammonia-fuelled vessels. Given ammonia's high toxicity and corrosiveness, a release poses significant safety and environmental hazards, and the club outlined response procedures, personal protective equipment and contingency planning that member ships should prepare.", "kImp": "암모니아 등 대체연료 도입이 확대되는 가운데, 유출 대응 미비는 오염·인명 P&I 클레임으로 직결될 수 있어 선제적 로스프리벤션 가이던스의 실무 중요성이 크다.", "eImp": "As alternative fuels like ammonia scale up, inadequate spill response can translate straight into pollution and injury P&I claims, making proactive loss-prevention guidance highly practical.", "url": "https://www.ukpandi.com/news-and-resources/news/article/ammonia-alternative-fuel-spill-response-considerations/"}, {"code": "PNI", "title": "UK P&I, 메탄올 대체연료 유출 대응 고려사항 안내", "src": "UK P&I Club", "date": "2026-07-23", "kSum": "UK P&I 클럽은 7월23일 메탄올 연료 선박의 유출 대응 고려사항을 담은 로스프리벤션 자료를 게시했다. 메탄올은 인화성이 높고 무색 화염으로 연소하는 등 취급 위험이 있어, 클럽은 유출·화재 시 대응 절차와 안전관리, 비상대비 사항을 회원 선박에 안내했다.", "eSum": "On 23 July UK P&I Club published loss-prevention material on spill-response considerations for methanol-fuelled vessels. Methanol is highly flammable and burns with a near-invisible flame, so the club set out response procedures, safety management and emergency preparedness for members handling a spill or fire.", "kImp": "메탄올 이중연료선 발주 확대와 맞물려, 연료 취급·유출 대응 역량은 화재·오염 P&I 리스크 관리의 핵심으로 부상하고 있다.", "eImp": "With methanol dual-fuel newbuildings rising, fuel-handling and spill-response capability is becoming central to managing fire and pollution P&I risk.", "url": "https://www.ukpandi.com/news-and-resources/news/article/methanol-alternative-fuel-spill-response-considerations/"}, {"code": "PNI", "title": "UK P&I, 로스프리벤션 영상 'Inside Ship: 블랙아웃' 공개", "src": "UK P&I Club", "date": "2026-07-30", "kSum": "UK P&I 클럽은 7월30일 로스프리벤션 교육 콘텐츠 'Inside Ship: Blackouts(선내 정전)'를 공개했다. 선박 전원상실(블랙아웃)은 조종불능·충돌·좌초 등 중대 사고로 이어질 수 있어, 영상은 발생 원인과 예방·복구 절차, 승조원 대응 요령을 다뤄 회원 선박의 안전운항을 지원한다.", "eSum": "On 30 July UK P&I Club released a loss-prevention training piece, 'Inside Ship: Blackouts'. A total loss of electrical power can lead to loss of manoeuvrability, collision or grounding, and the video covers causes, prevention and recovery procedures and crew response to support members' safe operations.", "kImp": "블랙아웃은 조종불능에 따른 충돌·좌초 등 대형 P&I·선체 클레임으로 이어질 수 있어, 예방 중심의 승조원 교육 콘텐츠는 사고·클레임 저감에 기여한다.", "eImp": "Blackouts can cascade into collisions and groundings driving large P&I and hull claims, so preventive crew-training content helps reduce incidents and claims.", "url": "https://www.ukpandi.com/news-and-resources/safety-advice-training/article/inside-ship-blackouts/"}]}, {"code": "VET", "type": "news", "kTitle": "Section 14. 베팅·검사", "eTitle": "Section 14. Vetting & Inspection", "items": [{"code": "VET", "title": "Paris MOU 2025 performance lists for Flag States and Recognized Organizations (best to worst)", "src": "maritimecyprus.com", "date": "2026-07-29", "kSum": "파리 MoU가 2025년 기국(Flag State)과 인정기관(RO) 성과 리스트를 공개했다. 69개 기국이 화이트(40)·그레이(17)·블랙(12) 리스트로 분류됐으며, 상위 기국은 케이맨제도·스웨덴·노르웨이·덴마크·일본이었고 상위 RO는 ABS·DNV·LR·ClassNK·BV 순이었다. 2025년 7월 1일부터 신규 성과 리스트가 선박위험도(Ship Risk Profile) 산정에 적용된다.", "eSum": "The Paris MoU released its 2025 Flag State and Recognized Organization (RO) performance lists. Of 69 flags rated, 40 are White-listed, 17 Grey and 12 Black; top flags are Cayman Islands, Sweden, Norway, Denmark and Japan, while ABS, DNV, LR, ClassNK and BV lead the ROs. The new lists apply to Ship Risk Profile calculations from 1 July 2025.", "kImp": "기국·선급 선택이 선박위험도와 PSC 점검 빈도, 용선 접근성에 직결되므로 화이트 리스트 기국과 고성과 RO 정렬이 상업적 리스크 관리의 핵심이다.", "eImp": "Flag and class choices directly drive a vessel's risk profile, PSC inspection frequency and charter access, making alignment with White-List flags and high-performing ROs a core commercial risk-management lever.", "url": "https://maritimecyprus.com/2026/07/29/paris-mou-2025-performance-lists-for-flag-states-and-recognized-organizations-ros-best-to-worst/"}, {"code": "VET", "title": "RightShip and NorthStandard collaborate to reduce duplicate inspections through secure report sharing", "src": "rightship.com", "date": "2026-07-29", "kSum": "라이트십(RightShip)과 노스스탠다드(NorthStandard)가 안전·리스크 인텔리전스와 보안 점검보고서 공유를 결합해 중복 점검을 줄이는 전략적 협업을 발표했다. 노스스탠다드는 라이트십의 기존 점검보고서를 요청·활용해 별도의 클럽 컨디션 서베이 필요성을 줄일 수 있다. 드라이벌크 선박관리사 오리온 리더라이(Orion Reederei)가 운영모델 검증에 참여했다.", "eSum": "RightShip and NorthStandard announced a strategic collaboration combining safety and risk intelligence with secure inspection-report sharing to cut duplicate inspections. NorthStandard can request existing RightShip inspection reports, reducing the need for separate club condition surveys. Dry bulk manager Orion Reederei helped test the operating model.", "kImp": "다수 이해관계자의 중복 점검 부담을 줄이는 신뢰 기반 보고서 공유는 선원 업무 부담을 완화하고 벳팅·보증 절차의 효율성과 표준화를 높인다.", "eImp": "Trusted report sharing that cuts overlapping inspections from multiple stakeholders eases crew workload and pushes vetting and vessel-assurance toward greater efficiency and standardization.", "url": "https://rightship.com/insights/press-release-rightship-and-northstandard-collaborate-to-reduce-duplicate-inspections-through-secure-inspection-report-sharing"}]}, {"code": "CLASS", "type": "news", "kTitle": "Section 15. 선급", "eTitle": "Section 15. Classification Societies", "items": [{"code": "CLASS", "title": "ABS, 삼성중공업·콘래드 조선소의 미국 건조 LNG 벙커링 ATB 설계에 기본승인(AiP) 부여", "src": "ABS", "date": "2026-07-28", "kSum": "미국선급(ABS)이 삼성중공업(SHI)과 미국 콘래드 조선소(Conrad Shipyard)에 미국 내 건조를 목표로 한 12,000㎥급 LNG 벙커링 접이식 예인선-바지선(ATB) 기본설계에 대해 기본승인(AiP)을 부여했다. 이번 승인은 워싱턴 D.C.에 설립된 한미조선협력센터(KUSPC)에서 도출된 첫 성과 중 하나로, 양사 간 공동건조 양해각서에 이은 후속 조치다.", "eSum": "ABS awarded Samsung Heavy Industries (SHI) and Conrad Shipyard an Approval in Principle (AiP) for the basic design of a 12,000 cubic meter LNG bunkering articulated tug-barge (ATB) intended for construction in the United States. The AiP is among the first initiatives from the Korea-U.S. Shipbuilding Partnership Center (KUSPC) in Washington, D.C., following an MOU between the two firms for joint ATB construction.", "kImp": "미국 내 LNG 벙커링 인프라 확충과 한미 조선 협력의 구체적 성과를 보여주는 사례로, 미국 건조 규정과 LNG 연료 공급망 요건을 동시에 충족하는 설계 방향을 제시한다.", "eImp": "It signals concrete Korea-U.S. shipbuilding cooperation and the build-out of U.S. LNG bunkering infrastructure, offering a design pathway that meets both U.S.-build requirements and LNG fuel-supply-chain needs.", "url": "https://gcaptain.com/abs-awards-approval-in-principle-to-samsung-heavy-industries-and-conrad-shipyard-for-u-s-built-lng-bunkering-atb/"}, {"code": "CLASS", "title": "뷰로베리타스, 시트리움 30MW 부유식 데이터센터 콘셉트에 기본승인(AiP) 부여", "src": "Bureau Veritas", "date": "2026-07-28", "kSum": "뷰로베리타스(Bureau Veritas) 마린&오프쇼어가 싱가포르 시트리움(Seatrium)의 30MW 부유식 데이터센터 콘셉트에 기본승인(AiP)을 부여했다. 해당 설계는 계류식 비자항 바지선에 각각 IT 장비·냉각·전력분배를 갖춘 5MW급 'Data-in-a-Box' 모듈 6기를 탑재하는 구조로, 자연 해수 냉각을 활용한다.", "eSum": "Bureau Veritas Marine & Offshore granted an Approval in Principle (AiP) to Seatrium for its 30 MW floating data center concept. The jetty-moored, non-propelled barge houses six independent 5 MW 'Data-in-a-Box' modules, each with IT equipment, cooling, power distribution and supporting infrastructure, using natural seawater cooling.", "kImp": "토지·전력 제약이 큰 연안 지역에서 컴퓨팅 용량을 확장하는 부유식 데이터센터라는 신개념 자산에 대한 선급 검증으로, 해상 인프라와 디지털 인프라가 결합하는 새로운 시장의 규정 기반을 마련한다.", "eImp": "It provides class validation for a novel asset type - offshore floating data centers - that expands computing capacity where land and power are constrained, laying regulatory groundwork for a market merging marine and digital infrastructure.", "url": "https://smartmaritimenetwork.com/2026/07/28/bv-grants-approval-for-seatrium-floating-data-centre-concept/"}, {"code": "CLASS", "title": "ClassNK, '컨테이너선 추가 소화 조치 지침' 제2.0판 발간", "src": "ClassNK", "date": "2026-07-27", "kSum": "일본선급(ClassNK)이 국제협약상 의무 요건을 넘어서는 컨테이너선의 추가 소화 조치를 평가하기 위한 '컨테이너선 추가 소화 조치 지침(제2.0판)'을 발간했다. 개정판은 취항 선박의 운항 경험과 최신 국제 동향을 반영해 래싱 브리지 소화전 설치, 갑판 화물구역 조기 화재 감지용 영상 감시 시스템 등을 추가했다.", "eSum": "ClassNK released Edition 2.0 of its 'Guidelines for Additional Fire-fighting Measures for Container Carrier,' providing criteria to evaluate fire-fighting measures beyond mandatory convention requirements. The update reflects in-service operational experience and adds fire hydrants on lashing bridges and video monitoring systems for early fire detection in weather-deck cargo areas.", "kImp": "대형 컨테이너선 화재가 반복되는 상황에서 실효적인 추가 소화 설비의 사양과 수량 기준을 제시해, 선사와 조선소가 비용 효율성을 고려하며 화재 대응력을 강화할 수 있는 지침을 제공한다.", "eImp": "Amid recurring large container-ship fires, it sets specifications and quantities for effective supplementary fire-fighting equipment, giving owners and yards guidance to strengthen fire response while weighing cost-effectiveness.", "url": "https://maritime-executive.com/corporate/classnk-releases-edition-2-0-of-the-guidelines-for-additional-fire-fighting-measures-for-container-carrier"}]}, {"code": "COMM", "type": "news", "kTitle": "Section 16. 상업·용선시장", "eTitle": "Section 16. Commercial & Chartering", "items": [{"code": "COMM", "title": "Drewry 세계컨테이너지수(WCI) 4% 하락, $4,374로 2주 연속 약세", "src": "gCaptain", "date": "2026-07-23", "kSum": "드류리(Drewry) 세계컨테이너지수(WCI)가 이번 주 4% 하락한 40피트당 $4,374를 기록하며 2주 연속 내렸다. 상하이-로스앤젤레스가 6% 하락한 $5,878, 상하이-뉴욕은 4% 내린 $7,598로 태평양 항로 약세가 두드러졌다. 선복 증가와 수요 둔화가 겹쳤고, 아시아-유럽도 상하이-제노바 5% 하락 등 완만히 약세를 보였다.", "eSum": "Drewry's World Container Index fell 4% to $4,374 per 40ft box, a second straight weekly decline. Transpacific led the drop (Shanghai-LA -6% to $5,878; Shanghai-NY -4% to $7,598) as added capacity met softening demand. Asia-Europe also eased, with Shanghai-Genoa down 5%. Carriers announced August emergency fuel surcharges citing Hormuz risk.", "kImp": "연초 이후 이어진 조기 성수기 랠리가 정점을 지났음을 시사한다. 다만 호르무즈(Hormuz) 리스크와 8월 관세 변수로 캐리어들이 8월 비상연료할증료(EFS)를 예고해 운임 하방을 제한할 수 있다.", "eImp": "Signals the early peak-season rally has passed its apex, though blank sailings, Hormuz risk and looming August tariffs could keep rates from falling sharply.", "url": "https://gcaptain.com/container-spot-rates-fall-as-capacity-growth-pressures-freight-rates/"}, {"code": "COMM", "title": "CMA CGM 2분기 순익 급증, 중동 혼란 속 운임 상승 수혜", "src": "gCaptain", "date": "2026-07-28", "kSum": "세계 3위 컨테이너 선사 CMA CGM(씨엠에이 씨지엠)이 2분기 매출 $157억(전년비 +19.2%), EBITDA $30억(+31%), 순이익 $7.7억을 기록했다. 해운 부문 매출이 22% 늘어난 $100억으로 실적을 견인했고, 운송량은 633만 TEU로 6% 증가했다. 중동 분쟁에 따른 보험료·선박 억류 비용 상승은 운임 상승으로 상쇄됐다.", "eSum": "CMA CGM posted Q2 revenue of $15.7bn (+19.2%), EBITDA of $3.0bn (+31%) and net income of $770m, driven by a 22% jump in shipping revenue to $10bn and 6.33m TEU carried. Higher freight rates and frontloading ahead of new tariffs offset Middle East disruption costs.", "kImp": "지정학적 불안에도 컨테이너 선사들이 강한 수익성을 유지하고 있음을 보여준다. 조기 성수기·관세 선적 수요가 실적을 뒷받침했으나, CMA CGM은 하반기 불확실성 확대를 경고했다.", "eImp": "Confirms liners are still highly profitable despite geopolitical turmoil, but CMA CGM warned of elevated uncertainty into H2 from Middle East tensions and shifting tariffs.", "url": "https://gcaptain.com/cma-cgm-posts-strong-q2-earnings-as-middle-east-disruptions-boost-shipping-rates/"}, {"code": "COMM", "title": "CMA CGM·Stonepeak, $96억 규모 글로벌 터미널 투자 플랫폼 출범", "src": "Splash247", "date": "2026-07-29", "kSum": "CMA CGM(씨엠에이 씨지엠)과 인프라 투자사 Stonepeak(스톤피크)이 United Ports(유나이티드 포츠) 합작법인 설립을 완료했다. Stonepeak이 $24억에 25% 지분을 인수하고 CMA CGM이 75%·운영권을 보유하며, 향후 항만 투자에 최대 $36억을 추가 투입해 총 규모 약 $96억에 이른다. 미국·유럽·아시아·남미의 9개 컨테이너 터미널을 포함한다.", "eSum": "CMA CGM and Stonepeak completed United Ports LLC, a terminal JV bundling nine container terminals across five countries. Stonepeak took a 25% stake for $2.4bn with CMA CGM holding 75% and control; a further $3.6bn is committed for future port investments, taking the platform to about $9.6bn.", "kImp": "컨테이너 선사가 인프라 자본을 끌어들여 터미널 네트워크를 확장하는 흐름을 보여주는 대형 M&A로, 항만 자산 밸류에이션과 선사-인프라펀드 제휴 확대를 시사한다.", "eImp": "A landmark deal showing liners tapping infrastructure capital to expand terminal networks, underscoring rising port-asset valuations and carrier-fund partnerships.", "url": "https://splash247.com/cma-cgm-and-stonepeak-launch-9-6bn-global-terminal-investment-platform/"}, {"code": "COMM", "title": "Ditas, DH조선 수에즈막스 2척 발주 연계 정황 (S&P·신조)", "src": "Splash247", "date": "2026-07-28", "kSum": "터키 선주 Ditas(디타스)가 한국 DH조선(구 대한조선)의 수에즈막스 유조선 2척과 연계된 것으로 파악됐다. 유조선 신조·자산 거래가 활발한 가운데 나온 딜로, 강세인 탱커 시장에서 선주들의 선대 확충 움직임을 반영한다.", "eSum": "Turkish owner Ditas has been linked to a pair of suezmax tankers at Korea's DH Shipbuilding, the latest in a busy run of tanker newbuilding and asset activity as owners expand fleets into a firm crude-tanker market.", "kImp": "기록적 발주가 이어지는 유조선 신조 시장의 활황을 보여주는 사례로, 조선소 수주잔량과 자산가치 상승 흐름과 맞닿아 있다.", "eImp": "Illustrates the red-hot tanker newbuilding cycle, tying into record orderbooks and rising asset values.", "url": "https://splash247.com/ditas-linked-to-dh-suezmax-pair/"}, {"code": "COMM", "title": "Diana Shipping, Genco 공개매수 철회…$27.34 인수 제안은 유지 (M&A)", "src": "Splash247", "date": "2026-07-28", "kSum": "그리스 선주 Diana Shipping(다이애나 십핑)이 미국 벌크선사 Genco(젠코)에 대한 적대적 공개매수를 7월 24일 만료 후 철회했으나, 주당 $27.34의 별도 인수 제안은 유지했다. 응모 주식은 Diana 미보유분의 31.6%에 그쳐 경영권 확보에는 실패했다. Diana는 Genco 지분 약 14.4%를 보유한 최대주주다.", "eSum": "Diana Shipping let its hostile tender for US dry bulk peer Genco expire on July 24 but kept its separate $27.34-per-share proposal alive. Only 31.6% of non-Diana shares were tendered, short of control. Diana remains Genco's largest holder at ~14.4%.", "kImp": "드라이벌크 업계의 대형 통합 시도가 교착에 빠졌음을 보여준다. Genco의 포이즌필(지분 15% 상한)이 방어에 작동했고, 협상은 장기화될 전망이다.", "eImp": "Shows a major dry-bulk consolidation attempt stalling; Genco's poison pill held, and negotiations look set to drag on.", "url": "https://splash247.com/diana-drops-genco-tender-as-takeover-talks-drag-on/"}, {"code": "COMM", "title": "중국 산둥항 조선소, 케미컬 탱커 신조 시장 진출 (신조)", "src": "Splash247", "date": "2026-07-28", "kSum": "중국 산둥항(Shandong Port) 계열 조선소가 케미컬 탱커 건조에 처음 진출했다. 탱커 발주가 기록적으로 늘어난 가운데 중국 조선소들이 유조선·케미컬선 등 고부가 선종으로 사업을 확장하는 흐름을 보여준다.", "eSum": "A Shandong Port-affiliated yard is breaking into chemical tanker construction, as Chinese builders expand into higher-value tanker segments amid a record surge in tanker ordering.", "kImp": "중국 조선소의 케미컬 탱커 진출은 한국·일본이 강세를 보여온 특수선 시장의 경쟁 심화를 예고한다.", "eImp": "Chinese entry into chemical tankers signals intensifying competition in a specialized segment long dominated by Korean and Japanese yards.", "url": "https://splash247.com/shandong-port-yard-breaks-into-chemical-tankers/"}, {"code": "COMM", "title": "관세 선적 효과 확인…트럼프, 60개국 대상 광범위 관세 재부과 (관세)", "src": "gCaptain", "date": "2026-07-24", "kSum": "트럼프 대통령이 7월 24일 60개 교역국을 대상으로 광범위 관세를 재부과하면서, 미국 수입업체들의 수개월간 선제 선적(frontloading)이 결실을 봤다. 관세 유예 만료 전 화물을 앞당겨 들여오려는 수요가 상반기 태평양 항로 운임과 물동량을 끌어올렸다.", "eSum": "President Trump reinstated broad tariffs on imports from 60 trading partners on July 24, validating months of frontloading by US importers who rushed cargo in before the deadline, a key driver of H1 transpacific volumes and rates.", "kImp": "관세 선적 수요가 상반기 운임 랠리의 핵심 동력이었음을 확인시켜 준다. 선제 물량 소진으로 하반기 태평양 물동량 둔화 리스크가 커진다.", "eImp": "Confirms tariff frontloading as a core driver of the H1 rate rally; with pull-forward exhausted, H2 transpacific volumes face downside risk.", "url": "https://gcaptain.com/tariff-driven-frontloading-pays-off-as-trump-reinstates-global-import-duties/"}]}, {"code": "GEO", "type": "news", "kTitle": "Section 17. 지정학", "eTitle": "Section 17. Geopolitics", "items": [{"code": "GEO", "title": "EU, 21차 대러 제재 채택…그림자선단 41척 추가·연료보급선 첫 지정", "src": "gCaptain", "date": "2026-07-24", "kSum": "EU가 21차 대러시아 제재 패키지를 채택해 그림자선단(shadow fleet) 선박 41척을 추가, 제재 대상 선박이 총 673척으로 늘었다. 처음으로 그림자선단에 급유하는 벙커선 5척과 선원공급업체를 지정했고, 100여 개 은행·암호화폐 사업자도 제재했다. 호르무즈 폐쇄에 따른 시장 혼란을 이유로 G7 유가상한제 자동조정은 2027년 7월까지 중단했다.", "eSum": "The EU adopted its 21st Russia sanctions package, adding 41 shadow-fleet vessels (total now 673) and, for the first time, five bunkering tankers that refuel them plus a crewing agency. Over 100 banks and crypto operators were also hit. The G7 oil-price-cap auto-adjustment was suspended until July 2027, citing Hormuz-driven market disruption.", "kImp": "그림자선단의 지원 인프라(급유·선원)까지 제재 범위를 넓힌 점이 핵심으로, 제재 회피 생태계 전반을 겨냥한 확전이다.", "eImp": "Extending sanctions to the fleet's support infrastructure (bunkering, crewing) marks an escalation targeting the entire evasion ecosystem.", "url": "https://gcaptain.com/eu-targets-russian-shadow-fleet-banks-and-crypto-in-sweeping-21st-sanctions-package/"}, {"code": "GEO", "title": "런던 보험시장, 후티 공격에 홍해 고위험구역 북쪽으로 확대", "src": "gCaptain", "date": "2026-07-30", "kSum": "런던 해상보험시장의 합동전쟁위원회(JWC)가 7월 29일 자문을 통해 홍해 고위험구역을 사우디 항만 인접 해역까지 북쪽으로 확대했다(이집트 수역은 제외). 후티(Houthi)가 7월 20일 사우디에 대한 해상봉쇄를 선언한 뒤 며칠 새 사우디 연계 선박 2척이 공격받은 데 따른 조치다.", "eSum": "London's Joint War Committee widened its Red Sea high-risk area northward toward Saudi ports (excluding Egyptian waters) in a July 29 advisory, after the Houthis' July 20 maritime embargo on Saudi Arabia and attacks on two Saudi-linked vessels.", "kImp": "고위험구역 확대는 전쟁위험보험료 상승과 항로 회피로 직결돼, 보험 가용성이 실제 선박 이동을 좌우하는 변수로 부상하고 있다.", "eImp": "A wider risk zone feeds directly into higher war-risk premiums and rerouting, with insurance availability becoming as decisive as the threat itself.", "url": "https://gcaptain.com/london-insurers-widen-red-sea-high-risk-zone-after-houthi-attacks/"}, {"code": "GEO", "title": "후티, 사우디 유조선 NCC GHAZAL 공격 주장…봉쇄 이후 4번째", "src": "gCaptain", "date": "2026-07-28", "kSum": "후티(Houthi)가 사우디 해상봉쇄 선언 이후 4번째로 사우디 국적 케미컬·석유제품선 NCC GHAZAL을 탄도미사일로 공격했다고 주장했다. 선박은 남부 홍해 지잔(Jizan) 인근을 통항 중 회항한 것으로 전해졌다. UKMTO도 인근에서 폭발음을 보고했으나 선박·공격 여부는 확인하지 않았다.", "eSum": "The Houthis claimed a fourth attack on a Saudi-linked tanker since their blockade began, striking the Saudi-flagged chemical/products tanker NCC GHAZAL with ballistic missiles near Jizan in the southern Red Sea, forcing it to turn back. UKMTO reported an explosion nearby but did not confirm the vessel.", "kImp": "후티가 '봉쇄 대 봉쇄' 논리로 사우디 연계 선박에 대한 공격을 반복하며 홍해 해상안보를 재차 악화시키고 있음을 보여준다.", "eImp": "Repeated strikes under a 'siege for siege' logic show the Houthis steadily degrading Red Sea security for Saudi-linked shipping.", "url": "https://gcaptain.com/houthis-claim-fourth-attack-on-saudi-tanker-as-red-sea-blockade-intensifies/"}, {"code": "GEO", "title": "후티, 홍해에서 이란식 '호르무즈 통제' 모델 재현 노려", "src": "gCaptain", "date": "2026-07-28", "kSum": "예멘 정부 최고위 외교관은 후티(Houthi)가 이란의 호르무즈 해협 전략을 바브엘만데브(Bab el-Mandeb)에서 재현해 홍해 해운을 교란하려 하며, 국제사회의 미온적 대응에 고무돼 있다고 밝혔다. 두 개의 핵심 에너지 통항로가 동시에 위협받는 구도다.", "eSum": "Yemen's top diplomat said the Houthis aim to replicate Iran's Strait of Hormuz strategy in the Bab el-Mandeb, disrupting Red Sea shipping and emboldened by an insufficient international response, putting two critical energy chokepoints at risk simultaneously.", "kImp": "호르무즈와 바브엘만데브의 '쌍둥이 초크포인트' 위협이 현실화하면 중동발 에너지 물류의 우회로마저 봉쇄돼 글로벌 공급 리스크가 급증한다.", "eImp": "A materializing 'twin chokepoint' threat would close off even the alternative route for Middle East energy, sharply raising global supply risk.", "url": "https://gcaptain.com/houthis-pushing-to-model-irans-hormuz-control-in-red-sea/"}, {"code": "GEO", "title": "사우디, 후티 도시 호데이다에 보복 공습", "src": "The Maritime Executive", "date": "2026-07-24", "kSum": "사우디가 자국 선박에 대한 후티(Houthi)의 잇단 공격에 대응해 후티 점령 도시 호데이다(Hodeidah)를 공습했다. 2022년 휴전 이후 소강상태였던 사우디-후티 전선이 후티의 사우디 해운 공격으로 다시 불붙었다. 앞서 수요일 후티 드론·미사일에 사우디 유조선 2척이 피격됐다.", "eSum": "Saudi forces struck the Houthi-held city of Hodeidah in retaliation for the group's attacks on Saudi shipping, reigniting a front largely dormant since the 2022 truce. Two Saudi tankers had been hit by Houthi drones and missiles days earlier.", "kImp": "사우디의 지상·항만 도시 타격은 해상 봉쇄 분쟁이 육상 군사 충돌로 번지는 위험한 확전을 의미하며, 홍해 해운 리스크를 한층 키운다.", "eImp": "Saudi strikes on a port city mark a dangerous spillover of the maritime blockade into land-based military conflict, raising Red Sea shipping risk further.", "url": "https://maritime-executive.com/article/saudi-arabia-launches-retaliatory-strikes-on-houthi-city-of-hodeidah"}, {"code": "GEO", "title": "값싼 드론이 해운의 전쟁위험 지도를 다시 그린다", "src": "Splash247", "date": "2026-07-28", "kSum": "저비용 드론과 무인 공격정이 홍해·걸프·흑해·카스피해 등지에서 상선을 위협하는 새로운 비대칭 위협으로 부상하며, 해운업계의 전쟁위험 지도가 근본적으로 재편되고 있다는 분석이다. 값싼 무기로 고가 선박을 위협할 수 있게 되면서 위험 산정과 보험이 복잡해지고 있다.", "eSum": "Cheap drones and uncrewed attack craft are emerging as an asymmetric threat to merchant ships across the Red Sea, Gulf, Black Sea and Caspian, fundamentally redrawing shipping's war-risk map as low-cost weapons menace high-value vessels.", "kImp": "저비용 무기의 확산은 특정 초크포인트를 넘어 광범위한 해역에서 상시적 위협을 만들어, 전쟁위험보험과 항로 선택의 패러다임을 바꾸고 있다.", "eImp": "The spread of low-cost weapons creates persistent, geographically diffuse threats beyond single chokepoints, reshaping war-risk insurance and routing.", "url": "https://splash247.com/cheap-drones-redraw-shippings-war-risk-map/"}, {"code": "GEO", "title": "러시아 공습에 우크라이나 흑해 항만 기항 중단", "src": "gCaptain", "date": "2026-07-23", "kSum": "러시아의 공습 강화로 선주들이 우크라이나 흑해 항만 기항을 중단했다고 키이우가 밝혔다. 젤렌스키 대통령은 러시아가 우크라이나의 주요 곡물 수출 회랑을 봉쇄하기 위해 공격을 확대할 수 있다고 경고했다.", "eSum": "Shipowners halted arrivals at Ukraine's Black Sea ports amid intensified Russian strikes, Kyiv said, with President Zelensky warning Moscow may escalate to block the country's main grain-export corridor.", "kImp": "흑해 곡물 회랑에 대한 위협 고조는 글로벌 식량 물류와 곡물가에 직접적 파장을 미치며, 또 하나의 분쟁 해역 리스크를 부각한다.", "eImp": "Rising threats to the Black Sea grain corridor directly affect global food logistics and prices, highlighting another conflict-zone shipping risk.", "url": "https://gcaptain.com/shipowners-halt-calls-at-ukraines-black-sea-ports-wary-of-russian-strikes/"}, {"code": "GEO", "title": "러시아, 오데사 인근 선박 2척 추가 타격 주장", "src": "The Maritime Executive", "date": "2026-07-29", "kSum": "러시아 국방부가 오데사(Odesa) 항 인근에서 선박 2척과 해안 인프라를 추가로 타격했다고 주장했다. 러시아는 해당 선박들이 우크라이나군용 무기를 운송했다고 주장했으나, 우크라이나의 흑해 회랑은 GDP의 상당 부분을 차지하는 곡물 수출에도 핵심적이다.", "eSum": "Russia's defense ministry claimed strikes on two more ships near Odesa along with shoreside infrastructure, alleging they carried arms for Ukraine's military; the Black Sea corridor also carries the bulk of Ukraine's economically vital grain exports.", "kImp": "흑해 상선에 대한 러시아의 반복 공격은 우크라이나 수출 회랑의 안정성을 위협하고 선원 안전·보험 비용을 끌어올린다.", "eImp": "Repeated Russian strikes on merchant ships threaten the stability of Ukraine's export corridor and drive up crew-safety and insurance costs.", "url": "https://maritime-executive.com/article/russia-claims-strikes-on-two-more-ships-near-odesa"}, {"code": "GEO", "title": "러시아, 올해 첫 비쇄빙 LNG선 북극 LNG2로…제재 우회 북극항로 확대", "src": "gCaptain", "date": "2026-07-29", "kSum": "러시아가 제재 대상인 북극 LNG2 프로젝트로 올해 첫 비(非)쇄빙 LNG 운반선을 보냈고, 인근에는 원유 유조선단이 북극항로(NSR) 하계 통항을 위해 집결했다. 서방 제재에도 북극 해운에 대한 의존을 키우며 에너지 수출을 지속하려는 움직임이다.", "eSum": "Russia dispatched its first conventional (non-ice-class) LNG carrier of the year to the sanctioned Arctic LNG 2 project as a fleet of crude tankers gathered for a summer Northern Sea Route push, underscoring Moscow's growing reliance on Arctic shipping to sustain exports despite sanctions.", "kImp": "제재 회피를 위한 북극항로 활용 확대는 그림자선단·환경 리스크와 함께 러시아 에너지 수출 통제의 새로운 전선을 형성한다.", "eImp": "Expanded Arctic-route use for sanctions evasion opens a new front in controlling Russian energy exports, alongside shadow-fleet and environmental risks.", "url": "https://gcaptain.com/russia-sends-first-conventional-lng-carrier-to-arctic-lng-2-as-oil-tankers-gather-for-nsr-push/"}]}, {"code": "TW", "type": "news", "kTitle": "Section 18. TradeWinds 선박관리", "eTitle": "Section 18. TradeWinds Ship Management", "items": [{"code": "TW", "title": "Mercuria takes Union Maritime newcastlemaxes on long-term charter", "src": "TradeWinds", "date": "2026-07-29", "kSum": "트레이딩 하우스 메르쿠리아(Mercuria)가 런던 기반 선주 유니온 마리타임(Union Maritime)의 뉴캐슬막스 선박들을 장기 용선한 것으로 전해졌다.", "eSum": "Trading house Mercuria has taken newcastlemax bulkers from London-based owner Union Maritime on long-term charter, according to the headline.", "kImp": "장기 용선 계약은 선주의 안정적 수익 확보와 대형 벌크선 수요를 반영한다.", "eImp": "Long-term charter deals underpin owner earnings visibility and reflect firm demand for large bulk carriers.", "url": "https://www.tradewindsnews.com/bulkers/mercuria-takes-union-maritime-newcastlemaxes-on-long-term-charter/2-1-2022101"}, {"code": "TW", "title": "Performance Shipping earnings move higher as fleet growth builds top line", "src": "TradeWinds", "date": "2026-07-29", "kSum": "뉴욕 상장 선주 퍼포먼스 시핑(Performance Shipping)의 실적이 선대 확대에 힘입어 매출이 늘며 개선된 것으로 전해졌다.", "eSum": "New York-listed owner Performance Shipping saw earnings move higher as fleet growth lifted its top line, per the headline.", "kImp": "선대 성장을 통한 실적 개선은 상장 선주의 투자·확장 전략 성과를 가늠하게 한다.", "eImp": "Earnings gains driven by fleet growth gauge the payoff of a listed owner's investment and expansion strategy.", "url": "https://www.tradewindsnews.com/tankers/performance-shipping-earnings-move-higher-as-fleet-growth-builds-top-line/2-1-2022428"}, {"code": "TW", "title": "Greek shipowner W Marine breaks into ultramax newbuildings with hat-trick in China", "src": "TradeWinds", "date": "2026-07-29", "kSum": "그리스 선주 W 마린(W Marine)이 중국에서 울트라막스 신조선 3척을 발주하며 해당 선형에 처음 진출한 것으로 전해졌다.", "eSum": "Greek shipowner W Marine has broken into ultramax newbuildings with a hat-trick of orders in China, according to the headline.", "kImp": "신규 선형 진출과 중국 발주는 그리스 선주의 벌크 선대 다변화 흐름을 보여준다.", "eImp": "Entering a new vessel type via Chinese orders illustrates Greek owners' continued diversification of their bulker fleets.", "url": "https://www.tradewindsnews.com/bulkers/greek-shipowner-w-marine-breaks-into-ultramax-newbuildings-with-hat-trick-in-china/2-1-2021904"}, {"code": "TW", "title": "Turkish owner sells bulker to up-and-coming shipowner in agricultural trade", "src": "TradeWinds", "date": "2026-07-27", "kSum": "튀르키예 선주가 농산물 트레이드에 종사하는 신흥 선주에게 벌크선 1척을 매각한 것으로 전해졌다.", "eSum": "A Turkish owner has sold a bulker to an up-and-coming shipowner active in the agricultural trade, according to the headline.", "kImp": "신흥 선주의 선대 확보는 중고선 시장 활력과 선주 지형의 세대 교체를 보여준다.", "eImp": "A newcomer building tonnage signals an active secondhand market and generational change in the ownership landscape.", "url": "https://www.tradewindsnews.com/bulkers/turkish-owner-sells-bulker-to-up-and-coming-shipowner-in-agricultural-trade/2-1-2020434"}]}, {"code": "HOT", "type": "news", "kTitle": "Section 19. 핫이슈: 호르무즈 해협", "eTitle": "Section 19. Hot Topic: Strait of Hormuz", "items": [{"code": "HOT", "title": "카타르, 3주 만에 호르무즈 통해 첫 LNG 화물 통항", "src": "gCaptain", "date": "2026-07-30", "kSum": "카타르가 자국 LNG선이 7월 7일 호르무즈(Hormuz)에서 피격된 지 3주여 만에 처음으로 해협을 통해 LNG 화물을 내보냈다. LNG선 Al Areesh가 트랜스폰더를 켠 채 해협을 통과해 목요일 오만만으로 진입했으며, 파키스탄행으로 신호했다. 라스라판 인근에는 12척 이상의 LNG선이 대기 중이다.", "eSum": "Qatar sent its first LNG cargo through the Strait of Hormuz since one of its tankers was hit on July 7. The carrier Al Areesh transited with its transponder on, entering the Gulf of Oman Thursday and signaling Pakistan. More than a dozen LNG carriers are idling near Ras Laffan.", "kImp": "세계 최대 LNG 공급국의 통항 재개는 시장에 부분적 안도를 주지만, 미·이란 공습 재개로 흐름이 다시 끊길 위험이 상존해 글로벌 LNG 수급이 여전히 타이트하다.", "eImp": "A resumption by the world's top LNG supplier offers partial relief, but renewed US-Iran strikes risk cutting flows again, keeping the global LNG market tight.", "url": "https://gcaptain.com/qatar-sends-first-lng-shipment-through-hormuz-in-three-weeks/"}, {"code": "HOT", "title": "UAE, 긴장에도 페르시아만 LNG 수출 강행", "src": "gCaptain", "date": "2026-07-29", "kSum": "아부다비국영석유회사(ADNOC)가 역내 적대행위 재개로 생산국들이 호르무즈(Hormuz) 통항을 축소하는 와중에도 페르시아만 LNG 수출을 이어가고 있다. ADNOC 소속 빈 LNG선은 위치신호를 끈 채 해협을 반대방향으로 통과해 걸프로 진입한 것으로 확인됐다.", "eSum": "Abu Dhabi's ADNOC is pressing ahead with Persian Gulf LNG exports even as renewed hostilities force producers to curb visible Hormuz traffic. An empty ADNOC LNG carrier crossed the strait with its transponder off to enter the Gulf.", "kImp": "주요 생산국들이 트랜스폰더를 끄는 '다크 통항'으로 수출을 유지하는 방식은 위험구역에서의 상업 활동 지속과 함께 해상 투명성·안전 우려를 키운다.", "eImp": "Producers sustaining exports via 'dark' transits show commerce persisting in a war zone while raising maritime-transparency and safety concerns.", "url": "https://gcaptain.com/uae-presses-ahead-with-persian-gulf-lng-exports-despite-tensions/"}, {"code": "HOT", "title": "외교 재개 속 이란, 호르무즈서 '위반' 선박 기뢰 피격 주장", "src": "The Maritime Executive", "date": "2026-07-26", "kSum": "이란 국영매체가 일요일 이란 통항구역 밖을 항행하던 '위반' 유조선이 호르무즈(Hormuz)에서 기뢰에 피격돼 폭발했다고 주장했다. 미국은 외교적 노력을 위해 군사작전을 일시 중단했고, 이란 외교관들은 오만과 해협 안전통항 원칙·운영방식을 논의하기 위해 대화를 재개했다. 통항은 이란 연계 선박조차 거의 멈춘 상태다.", "eSum": "Iranian state media claimed a 'violating' tanker struck a mine and exploded in the Strait of Hormuz while navigating outside the Iranian transit zone. The US paused military operations to allow diplomacy, and Iranian diplomats reopened talks with Oman on safe-passage principles, though traffic remains near-halted even for Iran-linked ships.", "kImp": "기뢰 위협과 이란의 독자 통항 규칙이 결합돼 해협 전역이 '극단적 위험구역'으로 취급되며, 외교 재개에도 통항 회복은 지지부진하다.", "eImp": "Mine threats combined with Iran's unilateral transit rules keep the whole strait treated as an extreme-risk zone, with transits recovering little despite renewed diplomacy.", "url": "https://maritime-executive.com/article/as-diplomacy-picks-up-iran-claims-mine-strike-on-ship-in-strait-of-hormuz"}, {"code": "HOT", "title": "미군, 호르무즈에서 이란 연계 유조선 또 타격", "src": "The Maritime Executive", "date": "2026-07-24", "kSum": "미 중부사령부(CENTCOM)에 따르면 미군이 금요일 이란 항만 봉쇄를 돌파하려던 상선에 발포했다. 봉쇄 재개 이후 미군이 이란 연계 선박을 무력화한 두 번째 사례다. 해당 선박은 미국 제재 대상 VLCC로, 엔진룸에 사격을 받아 무력화됐다. 같은 날 인도 선원 28명이 탄 LPG선 Disha도 이란 영해에서 피격됐다.", "eSum": "US forces opened fire on a merchant vessel attempting to breach the blockade of Iranian ports, the second time since reimposing the cordon that the US has disabled an Iran-linked ship, firing into the engine room of a US-sanctioned VLCC. The same day, the LPG carrier Disha with 28 Indian crew was attacked in Iranian waters.", "kImp": "미국의 봉쇄 집행이 실제 무력 사용으로 이어지며, 상선이 미·이란 무력충돌의 최전선에 놓였음을 보여준다.", "eImp": "US enforcement of the blockade escalating to live fire shows merchant ships are now on the front line of US-Iran hostilities.", "url": "https://maritime-executive.com/article/u-s-forces-strike-another-iran-linked-tanker-in-strait-of-hormuz"}]}, {"code": "SYS", "type": "news", "kTitle": "Section 20. 시스템·앱", "eTitle": "Section 20. System & App", "items": [{"code": "SYS", "title": "Mintra, 노르웨이 국가 역량등록부와 교육이력 자동 연동", "src": "Smart Maritime Network", "date": "2026-07-28", "kSum": "선원 교육·역량관리 소프트웨어 기업 Mintra가 자사 학습·역량관리 시스템 TrainingPortal과 노르웨이 국가 디지털 역량등록부(K-REG) 간 통합을 개시했다. 교육 이수 기록이 국가 등록부에 자동 갱신되어 수작업 입력과 오류를 제거한다.", "eSum": "Crew training and competency software firm Mintra launched an integration between its TrainingPortal learning and competency management system and Norway's K-REG national digital competence registry, automatically updating training records in the national registry and removing manual entry and errors.", "kImp": "선원 자격·교육 이력의 자동화된 시스템 간 연동은 크루잉 SaaS의 핵심 가치로, 규제 보고 부담과 컴플라이언스 리스크를 줄인다. 국가 등록부 연계 사례는 향후 표준화된 선원 데이터 교환의 참조 모델이 된다.", "eImp": "Automated system-to-system linkage of seafarer credentials and training is a core crewing-SaaS value, cutting regulatory reporting burden and compliance risk. National-registry integration sets a reference model for standardised seafarer data exchange.", "url": "https://smartmaritimenetwork.com/2026/07/28/mintra-automates-norwegian-registry-training-record-updates/"}, {"code": "SYS", "title": "BIMCO, 디지털 선원증서 플랫폼 간 상호운용성 파일럿 추진", "src": "Smart Maritime Network", "date": "2026-07-29", "kSum": "BIMCO가 서로 다른 공급사 플랫폼 간 디지털 선원증서 데이터 교환을 시연하는 상호운용성 파일럿을 추진한다. IMO Compendium 데이터 모델을 공통 표준으로 사용하며, 9월 코펜하겐 워크숍에서 가상의 선원 신원과 전자증서를 플랫폼 간 손실 없이 내보내기·전송·가져오기·표시할 수 있는지 검증한다.", "eSum": "BIMCO will run an interoperability pilot to demonstrate exchange of digital seafarer certificate data between different providers' platforms, using the IMO Compendium data model as the common standard. A September Copenhagen workshop will test whether an artificial seafarer identity and e-certificates can be exported, transferred, imported and displayed across independent platforms without data loss.", "kImp": "선원 증서의 디지털화가 확산되는 가운데 벤더 종속(lock-in) 없는 플랫폼 간 상호운용성은 해운 IT 생태계 확장의 관건이다. 공통 데이터 표준 검증은 크루잉·컴플라이언스 시스템의 통합 비용을 낮춘다.", "eImp": "As seafarer certificates go digital, vendor-neutral cross-platform interoperability is critical to scaling the maritime IT ecosystem. Validating a common data standard lowers integration costs across crewing and compliance systems.", "url": "https://smartmaritimenetwork.com/2026/07/29/bimco-to-run-interoperability-pilot-for-digital-seafarer-certificate-vaults/"}]}, {"code": "SMGR", "type": "news", "kTitle": "Section 21. 선박관리사", "eTitle": "Section 21. Ship Managers", "items": [{"code": "SMGR", "title": "Anglo-Eastern, 2025 ESG 보고서 발간 - 지속가능 해운 이정표", "src": "Anglo-Eastern", "date": "2026-07-29", "kSum": "앵글로-이스턴(Anglo-Eastern)이 2025 ESG 보고서를 공개하며 2024년 말 기준 환경·사회·거버넌스 성과와 향후 지속가능한 해운을 위한 이행 방향을 제시했다. 750척 이상을 관리하는 대형 선박관리사가 배출 관리, 인력 안전, 거버넌스 개선 진전을 종합 보고했다.", "eSum": "Anglo-Eastern published its 2025 ESG Report, giving a snapshot of its environmental, social and governance performance at the close of 2024 and outlining continued steps toward a more sustainable maritime future. The manager of 750-plus vessels detailed progress on emissions management, workforce safety and governance.", "kImp": "세계 최대급 독립 선박관리사의 ESG 공시는 선주·용선주에게 규제 대응력과 관리 품질을 보여주는 신뢰 지표로, 업계 지속가능성 기준을 견인한다.", "eImp": "ESG disclosure from one of the world's largest independent ship managers is a trust signal to owners and charterers on regulatory readiness and management quality, and helps set the industry's sustainability benchmark.", "url": "https://www.angloeastern.com/news-and-insights/esg-report-2025-shaping-a-sustainable-maritime-future-copy/"}, {"code": "SMGR", "title": "Columbia·AD Ports 합작 Noatum CSM, 신임 CEO에 크시안토스 키리아코우 선임", "src": "Cyprus Shipping News", "date": "2026-07-28", "kSum": "컬럼비아 그룹(Columbia Group)과 AD Ports 그룹의 두바이 기반 선박관리 합작사 Noatum CSM이 크시안토스 키리아코우(Xanthos Kyriacou)를 신임 CEO로 선임했다. 컬럼비아에서 20년 이상 근무하며 이탈리아·튀르키예·중동 확장을 이끈 인물로, 합작사의 글로벌 사업 확대를 지휘한다.", "eSum": "Noatum CSM, the Dubai-based ship management joint venture between Columbia Group and AD Ports Group, appointed Xanthos Kyriacou as CEO. A 20-year Columbia veteran who most recently drove regional expansion across Italy, Turkey and the Middle East, he will lead the JV as it expands its global operations.", "kImp": "중동 선박관리 허브 성장의 핵심 합작사 리더십 강화로, 통합 해양 서비스 확장과 지역 관리 역량 제고가 기대된다.", "eImp": "Strengthened leadership at a key JV underpinning the Gulf as a rising ship management hub, signalling further expansion of integrated maritime services and regional capacity.", "url": "https://cyprusshippingnews.com/2026/07/28/columbia-group-and-ad-ports-group-appoint-xanthos-kyriacou-as-ceo-of-noatum-csm/"}, {"code": "SMGR", "title": "Synergy Marine, 호주 항해사관후보생 성장 사례로 선원 육성 조명", "src": "Synergy Marine", "date": "2026-07-29", "kSum": "시너지 마린 그룹(Synergy Marine Group)이 호주 항해 사관후보생 제이미 벨(Jamie Bell)의 성장 스토리를 소개하며, 실무 경험과 책임 부여를 통한 청년 선원 육성 프로그램을 조명했다. 후보생이 선박에서 기량과 글로벌 경험을 쌓아 항해사로 성장하는 과정을 담았다.", "eSum": "Synergy Marine Group profiled the journey of Australian Deck Officer Cadet Jamie Bell, highlighting how its cadet development programme builds skills, responsibility and global exposure at sea, from cadet to deck officer.", "kImp": "700척 이상을 관리하는 대형 관리사의 체계적 선원 육성은 인력난 대응과 승무원 유지·역량 확보의 핵심으로, 관리 품질과 안전 운항의 토대를 이룬다.", "eImp": "Structured seafarer development from a manager of 700-plus vessels is central to tackling the talent shortage and to crew retention and competency, underpinning management quality and safe operations.", "url": "https://www.synergymarinegroup.com/life-at-synergy/jamie-bell-deck-cadet-interview/"}]}]};